// Define a mutex for thread-safety
static pthread_mutex_t lock;

size_t writefunc(void *ptr, size_t size, size_t nmemb, char **dest) {
  size_t newlen = size*nmemb;

  // Lock the mutex before modifying data
  pthread_mutex_lock(&lock);
  memcpy(*dest, ptr, newlen);
  *dest += newlen;
  pthread_mutex_unlock(&lock);

  return newlen;
}

void fetchData(char* url, char** dest, size_t bytesToCopy) {
  CURL *curl = curl_easy_init();
  if(!curl) {
    fprintf(stderr, "Failed to initialize libcurl\n");
    exit(EXIT_FAILURE);
  }

