```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

struct Data {
    int *data;
    size_t used;
    size_t size;
};

void initData(struct Data *a, size_t initialSize) {
    a->data = (int*)malloc(initialSize * sizeof(int));
    a->used = 0;
    a->size = initialSize;
}

void insertData(struct Data *a, int element) {
    if (a->used == a->size) {
        a->size *= 2;
        a->data = (int*)realloc(a->data, a->size * sizeof(int));
    }
    a->data[a->used++] = element;
}

void freeData(struct Data *a) {
    free(a->data);
    a->data = NULL;
    a->used = a->size = 0;
}

double median(int* array, int n) {
    double median = 0;
    if (n % 2 == 0)
        median = (array[n/2 - 1] + array[n/2]) / 2.0;
    else
        median = array[n/2];

    return median;
}

int main() {
    CURL *curl;
    CURLcode res;
    struct Data data;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        initData(&data, 2); // Initializing the dynamic array
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com");
        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to fetch data: %s\n", 
                    curl_easy_strerror(res));
        } else {
            char *response = NULL; // replace with actual response
            int value;

            if (sscanf(response, "%d", &value) != 1) {
                fprintf(stderr, "Data corrupted\n");
            } else {
                insertData(&data, value);
            }
        }

        curl_easy_cleanup(curl);
    }

    if (data.used != 0) {
        qsort(data.data, data.used, sizeof(int), compareInts);
        printf("Median: %f\n", median(data.data, data.used));
    } else {
        printf("No data available\n");
    }

    freeData(&data);

    curl_global_cleanup();

    return 0;
}
```
This code simply fetches an integer from a webpage, checks if the data is valid and inserts it into a dynamic array. The median of the integers is calculated at the end. However, this program does not include any error handling for network failures or retry logic as these would require significantly more code and understanding of your exact use case. 

