import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from functools import partial
from third_party_api import ThirdPartyAPI

class FileStreamingService:
    def __init__(self, num_workers):
        self._executor = ThreadPoolExecutor(max_workers=num_workers)
        self.third_party_api = ThirdPartyAPI()

    def _stream_and_process_file(self, file_url, processing_func):
        try:
            with requests.get(file_url, stream=True) as response:
                for chunk in response.iter_content(chunk_size=8192): 
                    if chunk:  
                        result = processing_func(chunk)
                        self.third_party_api.send_data(result)
        except requests.exceptions.RequestException as e:
            print("There was an issue with the request", str(e))

    def stream_and_process_multiple_files(self, file_urls, processing_func):
        futures = [self._executor.submit(partial(self._stream_and_process_file, url, processing_func)) for url in file_urls]

        for future in as_completed(futures):
            err = future.exception()
            if err is not None:
                print("There was an error while streaming and processing the files", str(err))

    def dynamic_resource_allocation(self, file_size, processing_time):
        # Implement your logic here for resource allocation based on size and time. 
