import org.slf4j.LoggerFactory;

public class StateLoader {
    private static final Logger logger = LoggerFactory.getLogger(StateLoader.class);

    // In-memory cache
    private Map<String, Object> cache = new ConcurrentHashMap<>();
    // Loader configuration
    private Configuration config; 

    public StateLoader() {
        // Initialize the configuration
    }

    /**
     * Load a state object. If an appropriate version is available in memory, it will be returned from there.
     * Otherwise, it will attempt to load it from file/API and cache it for later use.
     */
    public Object loadState(String identifier) {
        Object state = null;

        // Check the cache first
        if (cache.containsKey(identifier)) {
            logger.info("Cache hit: {}", identifier);
            return cache.get(identifier);
        }

        try {
            switch (config.getSourceType()) {
                case FILE:
                    state = loadFromFile(config.getPath());
                    break;
                case API:
                    state = loadFromAPI(config.getEndpoint(), config.getAuthInfo());
                    break;
                default:
                    throw new IllegalStateException("Unknown source type");
            }
        } catch (IOException e) {
            logger.error("Error loading state from {}", config.getSourceType(), e);
            // Handle error according to the retry mechanism defined in configuration
        }

        if(state != null) cache.put(identifier, state);
        return state;
    }

