['Here is a high-level implementation of such a JavaScript function using Promises for asynchronous loading and error handling, along with a map for tracking script keys to prevent duplicates. 

```javascript
let loadedScripts = {}; // map for checking duplicate scripts

function fetchExternalScript(scriptObject) {
    return new Promise((resolve, reject) => {
        if (loadedScripts[scriptObject.key]) {
            resolve('Duplicate script - skipping load'); 
            return;
        }
        let scriptTag = document.createElement("script");
        scriptTag.src = scriptObject.src;
        scriptTag.async = !!scriptObject.async; // ensure it's a boolean

        if (scriptObject.code) {
            try {
                // inline code execution
                let blob = new Blob([scriptObject.code], {type: 'text/javascript'});
                scriptTag.src = URL.createObjectURL(blob);
            } catch(e) {
                reject('Code execution error: ', e);
            }
        }

        scriptTag.onload = () => resolve(`Script ${scriptObject.key} loaded successfully.`);
        scriptTag.onerror = (err) => 
          reject(`Failed to load script ${scriptObject.key}: ${err || 'unknown error'}`);

        document.body.appendChild(scriptTag); // assuming we want to append it in body
    });
}

function manageScripts(scriptObjects) {
    return Promise.allSettled(
      scriptObjects
          .sort((a, b) => b.priority - a.priority) // sorting by priority
          .map(fetchExternalScript)); // mapping each script to a promise
}
```
The `manageScripts` function accepts an array of `scriptObject` and returns a Promise that will resolve when all scripts have loaded successfully or rejected if any script failed. The scripts are sorted in descending order based on their priority before being mapped to promises, ensuring higher priority scripts are fetched first. 

