['Here's an example of a TypeScript solution that satisfies these requirements:

```typescript
import fetch from 'node-fetch';
import Redis from 'ioredis';

interface ElementMetadata {
  metadata: any;
  selector: string;
  timestamp: Date;
}

class DOMTraverser {
  private apiEndpoint = "http://api.metadata.com/";
  private cache: Redis.Redis;
  private batchSize = 100;
  private retryDelayMs = 5000;
  private maxRetries = 3;

  constructor() {
    this.cache = new Redis(); // replace with your actual Redis config
  }

  async getMetadata(selectors: string[]): Promise<ElementMetadata[]> {
    const cacheKeys = selectors.map((selector) => `metadata_${selector}`);
    let results: ElementMetadata[] = [];
    try {
      for (let i = 0; i < cacheKeys.length; i += this.batchSize) {
        const batchCacheKeys = cacheKeys.slice(i, i + this.batchSize);
        const cachedResultsPromises = batchCacheKeys.map((key) => this.cache.get(key));
        const cachedResults = await Promise.all(cachedResultsPromises);
        results = results.concat(cachedResults.filter((result) => result !== null).map((resultStr) => JSON.parse(resultStr)));
      }
    } catch (error) {
      console.log("Error getting from cache: ", error);
    }

    const uncachedSelectors = selectors.filter((selector, index) => results[index] === undefined);
    if (uncachedSelectors.length === 0) {
      return results;
    }

    for (let i = 0; i < uncachedSelectors.length; i += this.batchSize) {
      const batchUncachedSelectors = uncachedSelectors.slice(i, i + this.batchSize);
      let response: any[] | null = null;
      for (let retryCount = 0; retryCount < this.maxRetries && response === null; retryCount++) {
        try {
          const apiUrl = new URL(this.apiEndpoint);
          apiUrl.searchParams.append('selectors', batchUncachedSelectors.join(","));
          response = await fetch(apiUrl.toString()).then((res) => res.json());
        } catch (error) {
          console.log("Error calling API: ", error);
          await new Promise((resolve) => setTimeout(resolve, this.retryDelayMs));
        }
      }

      if (response !== null) {
        const batchResults = response.map((metadata, index) => ({ metadata, selector: batchUncachedSelectors[index], timestamp: new Date() }));
        const cachePipeline = this.cache.pipeline();
        batchCacheKeys.forEach((key, index) => cachePipeline.set(key, JSON.stringify(batchResults[index])));
        await cachePipeline.exec();
        results = [...results, ...batchResults];
      } else {
        console.log("API call failed after max retries");
      }
    }

    return results;
  }
}
```
This example uses node-fetch for making API calls, ioredis as a Redis client, and TypeScript's async/await syntax for handling promises. It implements batching, caching, retry mechanism with exponential backoff strategy and handles failures gracefully by returning cached results if available. 

