```Java
public class ChannelPool {
    private final BlockingQueue<SocketChannel> pool;

    public ChannelPool(int size) {
        this.pool = new ArrayBlockingQueue<>(size);
    }

    // Get a channel from the pool or create a new one if none are available
    public SocketChannel acquire() throws IOException {
        SocketChannel channel = pool.poll();
        if (channel == null) {
            return SocketChannel.open();
        } else {
            return channel;
        }
    }

    // Release a channel back to the pool for reuse
    public void release(SocketChannel channel) {
        pool.offer(channel);
    }
}
```
