use std::fs::File;
use std::io::Read;
use std::process::{Command, Stdio};
use serde_json::Value;
use std::sync::Arc;
use std::thread;
use std::time::Instant;
use tokio::sync::Mutex;
use once_cell::sync::Lazy;
use lazy_static::lazy_static;

#[derive(Debug, Deserialize)]
struct Config {
    arch: String,
    opt: String,
    flags: Vec<String>,
}

fn load_config(path: &str) -> Option<Config> {
    match File::open(path) {
        Ok(mut file) => {
            let mut contents = String::new();
            if file.read_to_string(&mut contents).is_ok() {
                serde_json::from_str(&contents).ok()
            } else {
                None
            }
        },
        Err(_) => None,
    }
}

lazy_static![COMPILER: Mutex<Option<String>> = Mutex::new(None);]

fn get_compiler() -> Arc<Mutex<Option<String>>> {
    static ref COMPILER: Mutex<Option<String>> = Mutex::new(None);
    Arc::clone(&COMPILER)
}

#[tokio::main]
async fn compile_with_metrics(config_path: &str) -> (i32, String, Option<Vec<u8>>) {
    let config = load_config(config_path).expect("Unable to load configuration");

    // Use the tokio runtime for concurrent execution.
    let mut handles = vec![];

    let before = Instant::now();

    // Run external process asynchronously
    let (child, tx) = tokio::process::Command::new("rustc")
        .args(&config.flags)
        .stdout(Stdio::piped())
        .spawn()
        .expect("Failed to spawn rustc");

    handles.push(tokio::task::spawn(async move {
        let mut output = String::new();
        child.wait_with_output().unwrap().stdout.take().map(|buf| output.extend(buf));

        // We're done with the handle now, so drop it
        std::mem::drop(child);

        let elapsed = before.elapsed();
        (elapsed.as_secs(), format_report(output), get_resource_bundle())
    }));

    // Wait for all tasks to complete and collect the results
    futures::future::join_all(handles).await.unwrap()
}

fn main() {
    let (exit, report, bundle) = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(compile_with_metrics("config.json"));

    printlnmacro![COMPILER: Mutex<Option<String>> = Mutex::new(None);]
```

The code above is a simplified version of what you're asking for. It doesn't cover all the points you mentioned, but hopefully it gives you an idea of how to approach this problem in Rust. 

