```rust
use std::fs::File;
use std::io::Read;
use std::path::Path;
use llvm_sys::LLVMInitializeNativeTarget;
use std::ffi::CString;
use std::os::raw::c_char;
use llvm_sys::{LLVMPassManagerBuilderCreate, LLVMDisposePassManagerBuilder, 
               LLVMParseIRInContext, LLVMGetFirstErrorMessage};

pub fn generate_ir(filename: &Path) -> Result<(), String> {
    let mut buf = String::new();
    File::open(&filename).map_err(|e| e.to_string())?
                         .read_to_string(&mut buf)?;

    unsafe {
        LLVMInitializeNativeTarget();
        let cstr = CString::new(buf).unwrap();

        let context = llvm_sys::LLVMGetGlobalContext();
        let module = LLVMParseIRInContext(context, cstr.as_ptr() as *const c_char, null(), null(), 0);

        if module.is_null() {
            return Err(String::from(std::ffi::CStr::from_ptr(LLVMGetFirstErrorMessage()).to_string()));
        }
    }

    Ok(())
}
```
