class PasswordVerifier {
    private $rateLimiter;
    private $logger;
    private $apiClient;

    public function __construct(RateLimiter $rateLimiter, Logger $logger, ApiClient $apiClient) {
        $this->rateLimiter = $rateLimiter;
        $this->logger = $logger;
        $this->apiClient = $apiClient;
    }

    public function verifyPassword($password, $ip) {
        if ($this->rateLimiter->isRateLimitExceeded($ip)) {
            $this->logger->log('Rate limit exceeded for IP: ' . $ip);
