['Here is an example code block that fulfills all your requirements using POSIX threads for thread safety and SQLite for database management. Note that this is a high-level overview and would require substantial implementation work to be fully functional. You should modify the function according to your FSA model and integrate it into your program as needed.

```c
#include <pthread.h>
#include <sqlite3.h>

typedef struct State {
    int value;
    struct State* next;
} State;

typedef struct Automaton {
    // Define FSA data members and methods here
} Automaton;

State* extendStateList(int* stateArray, size_t stateSize, Automaton *fsa, 
                       int lastIndex, sqlite3 *db) 
{
    pthread_mutex_lock(&dbMutex); // Lock for concurrency handling

    State* currentStates = NULL;
    State* newStateList = NULL;
    int rc = 0;
    char query[512];

    if(stateArray == NULL || stateSize <= 0) { 
        // Log and return error for invalid input
        pthread_mutex_unlock(&dbMutex);
        return NULL;
    }

    newStateList = (State*)malloc(sizeof(State)*stateSize);

    if(newStateList == NULL) { 
        // Log and return error for memory allocation failure
        pthread_mutex_unlock(&dbMutex);
        return NULL;
    }

    snprintf(query, sizeof(query), "INSERT INTO StateTable VALUES (%d, %s)", lastIndex+1, fsa->name);
    rc = sqlite3_exec(db, query, 0, 0, &errMsg); // Update DB with new state info

    if(rc != SQLITE_OK) {
        free(newStateList);
        pthread_mutex_unlock(&dbMutex);
        return NULL; // Log and return error for database operations failure
    }

    currentStates = newStateList; 
    snprintf(query, sizeof(query), "SELECT * FROM StateTable WHERE id <= %d", lastIndex);

    sqlite3_stmt *res;
    rc = sqlite3_prepare_v2(db, query, -1, &res, 0); // Fetch current states from DB

    if(rc != SQLITE_OK) { 
        free(newStateList);
        pthread_mutex_unlock(&dbMutex);
        return NULL; // Log and return error for database operations failure
    }

    int idx = 0;
    while(sqlite3_step(res) == SQLITE_ROW) {
        currentStates[idx].value = sqlite3_column_int(res, 1);
        if(idx > 0) { // Link states in the list
            currentStates[idx-1].next = &currentStates[idx];
        }
        idx++;
    }

    pthread_mutex_unlock(&dbMutex); // Release lock after completion of operation

    return newStateList; 
}
```

This is a skeleton code, you would need to fill in the missing pieces such as: defining your FSA model (`Automaton` struct), error checking and handling code for all functions where necessary. You should replace SQL queries according to your database schema. It also assumes that a global mutex `dbMutex` is available for controlling access to the database.
']

