```c
#include <pthread.h>
#include <assert.h>

typedef struct {
    char* path; // File path or URL to the resource bundle
    void* init_value;  // Initial value for the reduction
    int (*reduce)(void*, void*, size_t); // User-defined callback function for the reduction logic
} ResourceBundleParams;

typedef struct {
    ResourceBundleParams params;
    pthread_mutex_t mutex;
    int errorCode;
    void* reducedValue;
} ResourceBundleWorkerArgs;

void *fetchAndReduce(void *arg) {
    ResourceBundleWorkerArgs *workerArgs = (ResourceBundleWorkerArgs *) arg;
    ResourceBundleParams params = workerArgs->params;

    pthread_mutex_lock(&workerArgs->mutex);
    try{
        // Assume we have an external API that fetches the resource bundle and calls a callback function.
        fetchResourceBundle(params.path, params.reduce, params.init_value); 

        workerArgs->errorCode = 0; // Indicates success
    } catch (NetworkErrorException &e) {
        workerArgs->errorCode = -1; // Network failure error code
    } catch (InvalidURLErrorException &e) {
        workerArgs->errorCode = -2; // Invalid URL error code
    } catch (ServerSideErrorException &e) {
        workerArgs->errorCode = -3; // Server-side error code
    }
    pthread_mutex_unlock(&workerArgs->mutex);
    return NULL;
}

int processResourceBundle(char* path, void* init_value, int (*reduce)(void*, void*, size_t)) {
    ResourceBundleWorkerArgs workerArgs = {
        .params = {
            .path = path, 
            .init_value = init_value, 
            .reduce = reduce
        },
        .mutex = PTHREAD_MUTEX_INITIALIZER,
    };

    pthread_t thread;
    int rc = pthread_create(&thread, NULL, fetchAndReduce, (void *)&workerArgs);

    if(rc) {
        printf("ERROR: return code from pthread_create() is %d\n", rc);
        assert(0);
    }

    void *status;
    rc = pthread_join(thread, &status);

    if (rc){
        printf("ERROR: return code from pthread_join() is %d\n", rc);
        assert(0);
    }

    // Return the errorCode or reducedValue after unlocking mutex.
    pthread_mutex_lock(&workerArgs.mutex);
    int result = workerArgs.errorCode == 0 ? *((int*)workerArgs.reducedValue) : workerArgs.errorCode;
    pthread_mutex_unlock(&workerArgs.mutex);

    return result;
}
```

In a real-world scenario, the fetchResourceBundle function would use an actual API to fetch and process data asynchronously. Error codes and their meanings should be appropriately defined according to the external library's error handling policy. Also worth noting that this example does not include proper resource management for cases where you would need to free memory manually after using it, which is important in a real-world scenario. 

