['Below is a high-level implementation of the encryption library. This code does not cover all constraints due to complexity. 

```C
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>

typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} session_t;

session_t sessions[1024] = { 0 };

// Function to initialize a cipher context
int init_cipher(unsigned int id) {
    if (id >= 1024 || sessions[id].ctx != NULL) return -1; // invalid or used session id

    sessions[id].ctx = EVP_CIPHER_CTX_new();
    RAND_bytes(sessions[id].key, EVP_MAX_KEY_LENGTH);
    RAND_bytes(sessions[id].iv, EVP_MAX_IV_LENGTH);

    return 0;
}

// Function to encrypt data
int encrypt_data(unsigned int id, unsigned char* in, size_t length, unsigned char** out) {
    if (sessions[id].ctx == NULL) return -1; // uninitialized session

    EVP_EncryptInit_ex(sessions[id].ctx, EVP_aes_256_cbc(), NULL, sessions[id].key, sessions[id].iv);
    *out = malloc(length + EVP_MAX_BLOCK_LENGTH); // extra space for padding

    int outlen;
    EVP_EncryptUpdate(sessions[id].ctx, *out, &outlen, in, length);

    return outlen;
}

// Function to decrypt data
int decrypt_data(unsigned int id, unsigned char* in, size_t length, unsigned char** out) {
    if (sessions[id].ctx == NULL) return -1; // uninitialized session

    EVP_DecryptInit_ex(sessions[id].ctx, EVP_aes_256_cbc(), NULL, sessions[id].key, sessions[id].iv);
    *out = malloc(length + EVP_MAX_BLOCK_LENGTH); // extra space for padding

    int outlen;
    EVP_DecryptUpdate(sessions[id].ctx, *out, &outlen, in, length);

    return outlen;
}

// Function to clean up a cipher context
void cleanup_cipher(unsigned int id) {
    if (sessions[id].ctx == NULL) return; // uninitialized session

    EVP_CIPHER_CTX_free(sessions[id].ctx);
    sessions[id].ctx = NULL;
}
```
This is a simple example with only AES-256-CBC encryption and decryption. To handle all constraints, we would need to add much more complexity including managing session IDs securely, handling network disruptions and service outages, error handling, configuration system for setting parameters, and so on. It also needs more attention to security, performance optimization and concurrency.
