['Writing a complete library in C++ requires many files and classes which is beyond the scope of this platform. However, I can provide a simplified structure for such a system that you might want to use as a starting point for your project. This will be a very high-level overview, since full implementation would require much more code than could fit here:

```cpp
// Task.h
#pragma once
class Task {
public:
    virtual ~Task() {} // Polymorphic class needs virtual destructor
    virtual void run() = 0;  // Pure virtual function makes this an abstract base class
};

// WebServiceTask.h
#pragma once
#include "Task.h"
class WebServiceTask : public Task {
public:
    void run();
};

// MessageQueueTask.h
#pragma once
#include "Task.h"
class MessageQueueTask : public Task {
public:
    void run();
};
```

For managing tasks, we can use a thread pool:

```cpp
// ThreadPool.h
#pragma once
#include <vector>
#include <queue>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <functional>
#include <stdexcept>
#include "Task.h"
class ThreadPool {
public:
    ThreadPool(size_t);
    ~ThreadPool();

    template<typename F, typename... Args>
    auto enqueue(F&& f, Args&&... args) 
        -> std::future<typename std::result_of<F(Args...)>::type>;
private:
    // need to keep track of threads so we can join them
    std::vector< std::thread > workers;
    // the task queue
    std::queue< std::function<void()> > tasks;

    // synchronization
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};
```
To implement `ThreadPool`'s constructor and destructor:
```cpp
// ThreadPool.cpp
#include "ThreadPool.h"
ThreadPool::ThreadPool(size_t threads) :   stop(false) {
    for(size_t i = 0;i<threads;++i)
        workers.emplace_back([this] {
            while(true) {
                std::function<void()> task;
                {
                    std::unique_lock<std::mutex> lock(this->queue_mutex);
                    this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                    if(this->stop && this->tasks.empty())
                        return;
                    task = std::move(this->tasks.front());
                    this->tasks.pop();
                }
                task();
            }
        });
}
ThreadPool::~ThreadPool() {
    {
        std::unique_lock<std::mutex> lock(queue_mutex);
        stop = true;
    }
    condition.notify_all();
    for(auto &worker: workers)
        worker.join();
}
```
Then to implement `ThreadPool`'s `enqueue()` method:
```cpp
// ThreadPool.cpp (continued)
template<typename F, typename... Args>
auto ThreadPool::enqueue(F&& f, Args&&... args) 
    -> std::future<typename std::result_of<F(Args...)>::type> {
    using return_type = typename std::result_of<F(Args...)>::type;
    auto task = std::make_shared< std::packaged_task<return_type()> >(std::bind(std::forward<F>(f), std::forward<Args>(args)...));
    std::future<return_type> res = task->get_future();
    {
        std::unique_lock<std::mutex> lock(queue_mutex);
        if(stop)
            throw std::runtime_error("enqueue on stopped ThreadPool");
        tasks.emplace([task](){ (*task)(); });
    }
    condition.notify_one();
    return res;
}
```
For a full implementation, you would need to integrate this with your web services and message queue APIs, add logging, error handling, configuration management etc. This is just a starting point to demonstrate how one might structure such a system in C++. The library can be extended to support additional task types by creating new classes derived from the `Task` class.
']

