```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading;
using System.Diagnostics;
using Polly;
using Serilog;

public class WebSiteManager
{
    private readonly ConcurrentDictionary<string, string> _websites = new ConcurrentDictionary<string, string>();
    private readonly ILogger _logger = new LoggerConfiguration().WriteTo.Console().CreateLogger();

    public bool AddWebsite(string websitePath)
    {
        if (!_websites.TryGetValue(websitePath, out var status))
        {
            if (File.Exists(Path.Combine(websitePath, "web.config")))
            {
                _websites[websitePath] = "Not Started";
                _logger.Information("Website added: {@Status}", new { websitePath, status = "Not Started" });
                return true;
            }
            else
            {
                throw new WebConfigMissingException($"web.config file not found in {websitePath}");
            }
        }
        _logger.Information("Website already exists: {@Status}", new { websitePath, status });
        return false; // Website already added and started
    }

    public bool StartWebsite(string websitePath)
    {
        if (_websites.TryGetValue(websitePath, out var status))
        {
            try
            {
                var policy = Policy
                    .Handle<Exception>()
                    .WaitAndRetry(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

                policy.Execute(() =>
                {
