['Here is a simplified example in C demonstrating how such a function could be implemented using `jansson` library for JSON parsing and validation. It's not an exhaustive solution as there are many additional factors that should be considered to fully solve this problem. 

This example also does not handle load balancing, async processing or error handling for network latency. Also, it doesn't consider logging and unit tests which are usually needed for a real-world application. But the key parts like parsing json and checking fields are covered here. 

```c
#include <jansson.h>
#include <string.h>

int validate_json(char *json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        return -1;
    }

    if(!json_is_object(root)) {
        json_decref(root);
        return -1;
    }

    json_t *access_token = json_object_get(root, "access_token");
    if(!json_is_string(access_token) || !strlen(json_string_value(access_token))) {
        json_decref(root);
        return -1;
    }

    json_t *expires_in = json_object_get(root, "expires_in");
    if(!json_is_integer(expires_in) || json_integer_value(expires_in) <= 0 || json_integer_value(expires_in) >= 3600) {
        json_decref(root);
        return -1;
    }

    json_t *token_type = json_object_get(root, "token_type");
    if(!json_is_string(token_type) || strcmp("Bearer", json_string_value(token_type))) {
        json_decref(root);
        return -1;
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    if(refresh_token && (!json_is_string(refresh_token) || !strlen(json_string_value(refresh_token)))) {
        json_decref(root);
        return -1;
    }

    // Check for unexpected fields
    const char *key;
    json_t *value;
    json_object_foreach(root, key, value) {
        if(strcmp(key, "access_token") && strcmp(key, "expires_in") && strcmp(key, "token_type") && strcmp(key, "refresh_token")) {
            json_decref(root);
            return -1;
        }
    }

    // If all checks passed then cleanup and return success
    json_decref(root);
    return 0;
}
```
This function receives a JSON string, parses it into a JSON object tree using `jansson` library. It validates the required fields and returns -1 if any validation check fails. Otherwise it clean up the JSON object and return success (0).
']

