using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public class SecurityUtil {
    public static int? DecryptAndFindLargest(string encryptedMessage, byte[] key, byte[] iv) {
        try {
            //Decryption using Triple DES
            var tripleDes = new TripleDESCryptoServiceProvider();
            tripleDes.Key = key;
            tripleDes.IV = iv;

            var decryptedBytes = DecryptString(encryptedMessage, tripleDes);
            string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

            //Parsing the decrypted message into an array of integers
            int[] decryptedIntArray;
            try {
                decryptedIntArray = Array.ConvertAll(decryptedMessage.Split(' '), int.Parse);
            } catch (Exception e) {
                throw new Exception("Error while parsing the decrypted message into an integer array", e);
            }

            //Helper function to find and return the largest integer in this array
            if(decryptedIntArray.Length == 0) {
                return null;
            } else {
                return decryptedIntArray.Max();
            }
        } catch (Exception e) {
            throw new Exception("Error during decryption process", e);
        }
    }

    private static byte[] DecryptString(string input, SymmetricAlgorithm cryptoServiceProvider) {
        var encryptedBytes = Convert.FromBase64String(input);

        using (var memoryStream = new MemoryStream(encryptedBytes))
        using (var cryptoStream = new CryptoStream(memoryStream, cryptoServiceProvider.CreateDecryptor(), CryptoStreamMode.Read)) {
            byte[] decryptedBytes = new byte[encryptedBytes.Length];
            cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);

            return decryptedBytes;
        }
    }
}
```
