```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json; // For JSON deserialization

public class AESDecryptionService : IAESDecryptionService
{
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public AESDecryptionService(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
    }

    public async Task<T> DecryptAndDeserializeAsync<T>(string filePath) where T : class
    {
        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = _key;
                aesAlg.IV = _iv;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (FileStream fsIn = new FileStream(filePath, FileMode.Open))
                {
                    using (CryptoStream cs = new CryptoStream(fsIn, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] buffer = new byte[1024];
                        int read;
                        StringBuilder sb = new StringBuilder();

                        while ((read = await cs.ReadAsync(buffer, 0, buffer.Length)) > 0)
                        {
                            string text = Encoding.Unicode.GetString(buffer, 0, read);
                            sb.Append(text);
                        }

                        return JsonConvert.DeserializeObject<T>(sb.ToString());
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Decryption Error: {ex.Message}");
            throw;
        }
    }
}
```
