['Below is an example of how you could implement this utility using Java's built-in serialization and reflection APIs. For the logging part, I will use SLF4J, a widely-used logging framework that is compatible with many popular logging libraries. 

```java
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import java.lang.reflect.Constructor;
import java.nio.ByteBuffer;
import java.util.concurrent.locks.ReentrantLock;

public class DeserializationUtility {
    private static final Logger logger = LoggerFactory.getLogger(DeserializationUtility.class);
    private ReentrantLock lock = new ReentrantLock();

    public Object deserializeWithVersionCheck(byte[] data, Class<?> expectedClass, int expectedVersion) throws Exception {
        if (!lock.tryLock()) throw new InterruptedException("Failed to acquire lock");

        try (ByteArrayInputStream bais = new ByteArrayInputStream(data); 
             ObjectInput in = new ObjectInputStream(bais)) {
            int version = in.readInt(); // assuming the first four bytes are used for storing the version
            if (version != expectedVersion) {
                throw new DeserializationVersionMismatchException("Expected class version " + expectedClass 
                                                                      + " but found " + version);
            }

            Constructor<?> constructor = expectedClass.getDeclaredConstructor();
            return constructor.newInstance(in);
        } catch (IOException | DeserializationVersionMismatchException e) {
            logger.error("Deserialization error", e);
            throw e;
        } finally {
            lock.unlock();
        }
    }
}
```
