['Here's a rough outline of how you might implement such an application in Node.js using express. Please keep in mind that this is a simplified example and doesn't handle all the edge cases you specified (like logging, testing, etc). This is just to give you an idea about the structure.

```javascript
const express = require('express');
const app = express();
const retry = require('retry');
const docker = require('docker-modem');
const crypto = require('crypto');
const request = require('request-promise');

app.use(express.json()); // To parse incoming JSON data in POST requests

// Assuming an external service at URL 'http://auth-service/get_password'
async function getPassword() {
    const operation = retry.operation();
    let password;

    operation.attempt(async currentAttempt => {
        try {
            const response = await request('http://auth-service/get_password');
            password = crypto.createHash('sha256').update(response).digest('hex');
        } catch (err) {
            if (operation.retry(err)) {
                console.log(`Attempt ${currentAttempt} failed. Retrying...`);
                return;
            } else {
                throw err;
            }
        }
    });

    return password;
}

app.post('/modify_config', async (req, res) => {
    let config = req.body; // Assuming the JSON payload is in the body
    const sedCommands = Object.keys(config).map(placeholder => 
        `sed -i 's/${placeholder}/${config[placeholder]}/g' /path_to_your_file`); 

    try {
        const password = await getPassword(); // Retrieves the password securely
        sedCommands.push(`echo "EncryptedPassword=${password}" >> /path_to_your_file`);

        const containerId = docker.getContainer('YOUR_DOCKER_IMAGE').create({ Cmd: ['/bin/bash', '-c'] }).start().id;
        for (const cmd of sedCommands) {
            await docker.demuxer.docker({ path: `/containers/${containerId}/exec?cmd=%2Fbin%2Fbash+-c+${encodeURIComponent(cmd)}` });
        }

        res.status(200).json({ success: true, message: "Config file updated." });
    } catch (err) {
        console.error("Error updating config file.", err);
        res.status(500).json({ success: false, message: "Failed to update config file", error: err.message });
    }
