import requests
from multiprocessing import Pool
from functools import partial
from collections import defaultdict

class JSONTransformer(metaclass=abc.ABCMeta):
    def __init__(self, schema_url, schema_version):
        self.schema = self._get_latest_schema(schema_url, schema_version)

    @staticmethod
    def _get_latest_schema(schema_url, version=None):
        response = requests.get(schema_url)
        all_schemas = response.json()
        return all_schemas.get(version, all_schemas[max(all_schemas)])  # get the latest if no version provided

    @staticmethod
    def _validate_data(data, schema):
        try:
            jsonschema.validate(instance=data, schema=schema)
        except jsonschema.exceptions.ValidationError as err:
            return False, str(err)

        return True, None

    @abc.abstractmethod
    def transform_to_json(self):
        pass

    @abc.abstractmethod
    def transform_from_json(self):
        pass

class UserProfileTransformer(JSONTransformer):
