std::vector<ServiceConfig>* manageConfiguredServices(
    std::atomic<bool>& stopFlag, 
    std::mutex& mtx, 
    std::condition_variable& cv, 
    size_t lastIndex,
    std::vector<ServiceConfig>* serviceConfigsPtr, 
    ServiceRegistry& registry, 
    Logger& logger, 
    ExternalAPI& api) {

    // Prepare the return value
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [lastIndex]{ return lastIndex == serviceConfigsPtr->size(); });
    if (stopFlag.load())  {
        logger.log("Stop flag set, aborting configuration update.");
        return nullptr;
    }

    // Process the updates asynchronously to reduce latency
    std::thread updater([&]{
        try {
            for(size_t i = lastIndex; i < serviceConfigsPtr->size(); ++i) { 
                if (stopFlag.load()) break;

                // Update the configuration, handle exceptions and errors here
                std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate delay
            }
        } catch (const std::exception& e) {
            logger.log("Error while updating configurations: " + std::string(e.what()));

            // Rollback or other error handling here
            stopFlag = true;
        }

        // Notify waiting threads that we are done with the updates
        cv.notify_all(); 
    });

    updater.detach(); // Detach thread and let it run independently

    return serviceConfigsPtr;
}
