    OpenSSL_add_all_algorithms();

    // Set up Curl with necessary parameters and headers for OAuth2 authentication
    CURL *curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_USERAGENT, "libcurl-agent/1.0");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Return initialized curl for further operations
        return curl;
    }

    fprintf(stderr, "Failed to initialize crypto library.\n");
    return NULL;
}

Token *parse_token(const char *json) {
    json_t *root;
    json_error_t error;

    root = json_loads(json, 0, &error);

    // Check if JSON is correctly formatted
    if(!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return NULL;
    }

    json_t *access_token, *expires_in, *token_type, *refresh_token = NULL;

    // Extract fields from JSON
    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");

    // If refresh_token exists in JSON, extract it as well
    if(!json_is_null(refresh_token)) {
        refresh_token = json_object_get(root, "refresh_token");
    }

    // Check if all fields exist and have correct format
    if(!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type) 
        || strcmp(json_string_value(token_type), "Bearer")) {
        fprintf(stderr, "JSON validation failed.\n");
        json_decref(root);
        return NULL;
    }

    // Create token struct and populate fields
    Token *t = malloc(sizeof(Token));
    t->access_token = strdup(json_string_value(access_token));
    t->expires_in = json_integer_value(expires_in);
    t->token_type = strdup("Bearer");

    // If refresh_token exists, add it to the struct as well
    if(refresh_token) {
        t->refresh_token = strdup(json_string_value(refresh_token));
    } else {
        t->refresh_token = NULL;
    }

    // Clean up and return token struct
    json_decref(root);
    return t;
}
```
