    result.size = size;

    for (int i = 0; i < size; i++) {
        result.data[i] = rand() % 100 + 1;   // Random number between 1 and 100
    }

    return result;
}

double calculateMedian(DataList* list) {
    if (list->size == 0) return 0.0;

    // Sort the array in ascending order to easily find median
    qsort(list->data, list->size, sizeof(int), compare);

    if (list->size % 2 == 0) {
        // If size is even, median is average of two middle numbers
        return ((double)list->data[list->size / 2] + list->data[list->size / 2 - 1]) / 2;
    } else {
        // If size is odd, median is the middle number
        return (double)list->data[list->size / 2];
    }
}

void* dataProcessor(void* arg) {
    DataList list = fetchFromAPI();

    pthread_t threadId = pthread_self();
    syslog(LOG_INFO, "Thread %lu fetched and processed data", (unsigned long)threadId);

    double median = calculateMedian(&list);
    printf("The median value is: %f\n", median);

    free(list.data);
}

int main() {
    // Open connection to syslog
    openlog("DataProcessor", LOG_PID | LOG_NDELAY, LOG_USER); 

    const int numThreads = 10;  // Simulate handling of many concurrent requests
    pthread_t threads[numThreads];

    for (int i = 0; i < numThreads; i++) {
        if (pthread_create(&threads[i], NULL, dataProcessor, NULL)) {
            syslog(LOG_ERR, "Error creating thread");
            return 1;
        }
    }

    for (int i = 0; i < numThreads; i++) {
        if (pthread_join(threads[i], NULL)) {
            syslog(LOG_ERR, "Error joining thread");
            return 2;
        }
    }

    // Close connection to syslog
    closelog();

    return 0;
}
```

