#include <curl/curl.h>
#include <json-c/json.h>

// Define a structure to hold the data from each API call
typedef struct {
    char *data;
} DataSet;

DataSet* fetch_api(const char* url) {
    CURL *curl = curl_easy_init();
    if (!curl) return NULL;

    DataSet *ds = malloc(sizeof(*ds));
    ds->data = malloc(1); // Allocate memory to store data
    ds->data[0] = '\0';  // Null terminator for strcat

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, ds->data);

    // Perform the API call and check for errors
    if (curl_easy_perform(curl) != CURLE_OK) {
        free(ds->data); 
        free(ds);
        curl_easy_cleanup(curl);
        return NULL;
    }

    curl_easy_cleanup(curl);
    return ds;
}

void* fetch_thread(void *arg) {
    const char *url = (const char *) arg;
    DataSet *ds = fetch_api(url);
    pthread_exit((void*) ds);
}

int main() {
    curl_global_init(CURL_GLOBAL_ALL);

    // Define a list of URLs to fetch data from
    const char* urls[] = {"http://api1.com", "http://api2.com"};
    int num_urls = sizeof(urls) / sizeof(char*);

    pthread_t threads[num_urls];

    // Spawn a thread for each API call
    for (int i = 0; i < num_urls; ++i) {
        if (pthread_create(&threads[i], NULL, fetch_thread, urls[i]) != 0) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    // Wait for all threads to finish and print the data
    for (int i = 0; i < num_urls; ++i) {
        DataSet *ds;
        if (pthread_join(threads[i], (void**) &ds) == 0) {
            printf("%s\n", ds->data);
            free(ds->data); 
            free(ds);
        } else {
            fprintf(stderr, "Error joining thread\n");
        }
    }

    curl_global_cleanup();
    return 0;
}
```
This example uses POSIX threads for concurrent data fetching and libcurl to perform the API calls. The data from each API call is stored in a dynamically allocated `DataSet` structure, which is returned by the `fetch_api()` function. This function also handles errors during API calls and allocates memory to store the data.

Please note that this is a simplistic example for illustrative purposes. It doesn't include many of the features such as error handling, logging, security measures, etc. mentioned in your question. Implementing these would require additional steps and careful consideration of various factors like system dependencies, failover strategies, data recovery, performance optimization, modularity, integration with third-party APIs, monitoring and maintenance, input validation/sanitization for security purposes, scalability, robustness etc. 

