```java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.function.*;
import org.apache.commons.lang3.exception.*;
import com.google.common.cache.*;
import org.springframework.beans.factory.annotation.*;
import org.springframework.stereotype.*;

@Service
public class MoSTStateLoader {

    private LoadingCache<String, MostState> cache;
    private ServiceRegistry registry;
    private PerformanceLogger logger;

    @Autowired
    public MoSTStateLoader(ServiceRegistry registry, PerformanceLogger logger) {
        this.registry = registry;
        this.logger = logger;

        cache = CacheBuilder.newBuilder()
                .maximumSize(10_000) // configure based on expected load and resource limits
                .expireAfterWrite(30, TimeUnit.MINUTES) // configure based on use case
                .build(new CacheLoader<String, MostState>(){
                    @Override
                    public MostState load(String key) throws Exception {
                        return readFromFile(key);
                    }});
    }

    private MostState readFromFile(String filePath){
        try {
            // handle I/O operations with retries and exponential backoff
            BackOff backOff = new ExponentialBackOff();

            return registry.getStorage().readMostState(backOff.retry(() -> Files.newInputStream(Paths.get(filePath))));
        } catch (IOException | RetryException e) {
            throw ExceptionUtils.wrapAndThrowUnchecked(e);
        }
    }

    public MostState loadStateObjectFromFile(String filePath){
        try{
            logger.logStart();
            return cache.get(filePath);
        } catch (ExecutionException e) {
            logger.logError(e);
            return null;
        } finally {
            logger.logEnd();
        }
    }
}
```
