```cpp
// RandomLib.h
#pragma once
#include <random>
#include <memory>

class RandomGenerator {
public:
    virtual ~RandomGenerator() = default;
    virtual double generate(double min, double max) = 0;
};

class MersenneTwister : public RandomGenerator {
private:
    std::mt19937 mt;
    std::uniform_real_distribution<double> dis;
public:
    MersenneTwister(int seed);
    ~MersenneTwister() = default;
    double generate(double min, double max) override;
};

class RandomLib {
private:
    std::unique_ptr<RandomGenerator> gen;
public:
    RandomLib(std::unique_ptr<RandomGenerator>&& generator);
    ~RandomLib() = default;
    double generate(double min, double max);
};
```

And the corresponding .cpp file:

```cpp
// RandomLib.cpp
#include "RandomLib.h"

MersenneTwister::MersenneTwister(int seed) : mt(seed), dis(0.0, 1.0) {}
double MersenneTwister::generate(double min, double max) {
    return min + (max - min) * dis(mt);
}

RandomLib::RandomLib(std::unique_ptr<RandomGenerator>&& generator) : gen(std::move(generator)) {}
double RandomLib::generate(double min, double max) {
    return gen->generate(min, max);
}
```

In the above code, `MersenneTwister` is a concrete class that implements the `RandomGenerator` interface. It uses the Mersenne Twister algorithm from the standard library to generate random numbers with specified min and max values. 

The `RandomLib` class uses dependency injection to receive an instance of `RandomGenerator` as a constructor argument, making it easier to test and reuse in different contexts. The `generate()` method simply delegates the call to the injected generator.

