public class XMLService : IXMLService
{
    private readonly ILogger<XMLService> _logger;
    private IMemoryCache _cache;

    public XMLService(IMemoryCache memoryCache, ILogger<XMLService> logger)
    {
        _cache = memoryCache;
        _logger = logger;
    }

    public async Task<string> ParseAndValidateAsync(Stream xmlDoc, Stream schema)
    {
        // Load the schema from API asynchronously
        var schemaContent = await new StreamReader(schema).ReadToEndAsync();

        // Parse and validate XML against loaded schema 
        XmlDocument doc = new XmlDocument();
        doc.Schemas.Add("", XmlReader.Create(new StringReader(schemaContent)));
        doc.Load(xmlDoc);
        doc.Validate((o, e) => { _logger.LogError(e.Exception, "Validation Error"); }); 

        // Return parsed and validated XML as string
        return doc.OuterXml;
    }

    public async Task<string> FetchAndCacheAsync(string key, Func<Task<Stream>> loadData)
    {
        if (!_cache.TryGetValue(key, out Stream entry))// Look for cache key.
        {
            // Key not in cache, so get data and create cache entry.
            var entryOptions = new MemoryCacheEntryOptions()
                .SetSize(1)
                .SetPriority(CacheItemPriority.High)
                .SetSlidingExpiration(TimeSpan.FromMinutes(10)) // evict if not accessed for 10 minutes
                .RegisterPostEvictionCallback((key, value, reason, state) => { _logger.LogInformation("Entry was removed."); });

            using (var scope = new MemoryCacheScope(_cache))
            {
                entry = await loadData(); // get data from external service
                scope.Set(key, entry, entryOptions); // set in cache
            }
        }

        return await ParseAndValidateAsync(entry, await FetchSchemaFromAPI()); 
    }    
}
