// Function to read files recursively in the directory
async function processDirectory(dirPath) {
    const items = fs.readdirSync(dirPath);

    for (const item of items) {
        const fullPath = path.join(dirPath, item);

        if (fs.statSync(fullPath).isFile()) {
            await processFile(fullPath);
        } else if (fs.statSync(fullPath).isDirectory() && fs.readdirSync(fullPath).length > 0) {
            // If you want to limit the depth of recursion, add an additional condition here 
            await processDirectory(fullPath);
        }
    }
}

// Function to process a file based on its extension and size
async function processFile(filePath) {
    const extension = path.extname(filePath).toLowerCase();

    if (config.extensions && config.extensions.includes(extension)) {
        const stats = fs.statSync(filePath);

        if (config.sizeLimits && stats.size > config.sizeLimits) {
            // process the file...
            console.log("Processing " + filePath);
        } else {
            console.warn(`File ${filePath} too large: ${stats.size} bytes`);
        }
    } else {
        console.warn('Ignoring ' + filePath);
    }
}

// Start processing files from a specified directory
processDirectory(config.directory)
    .catch((err) => {
      console.error("Error occurred during file processing:", err);
    });
