use reqwest::Error;
use serde::Deserialize; // for parsing JSON responses
use std::collections::HashMap;
use typer::Typer;

#[derive(Debug, Deserialize)]
struct AuthResponse {
    access_token: String,
}

type RequestBuilder = Box<dyn Fn(&str) -> reqwest::RequestBuilder + Send + Sync>;

pub struct HttpClient {
    client: reqwest::Client,
    auth: Option<AuthResponse>,
    retry_attempts: usize,
}

impl HttpClient {
    fn new(auth_url: &str, retries: usize) -> Self {
        let client = reqwest::Client::new();
        match client.get(&auth_url).send() {
            Ok(mut resp) => {
                let auth = match resp.json::<AuthResponse>() {
                    Ok(auth) => Some(auth),
                    Err(_e) => None,
                }
                HttpClient {
                    client,
                    auth,
                    retry_attempts: retries,
                }
            },
            Err(_e) => HttpClient {
                client,
                auth: None,
                retry_attempts: retries,
            },
        }
    }

    async fn get(&self, url: &str, headers: HashMap<&str, &str>) -> Result<(), Error> {
        let mut request = self.client.get(url);
        for (k, v) in &headers {
            request = request.header(k, v);
        }

        match request.send().await {
            Ok(_response) => println_something(), // Handle response here
            Err(e) => return Err(e),
        };

        Ok(())
    }

