```C
#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <unistd.h>

void processFile(char *filename) {
    // This is a placeholder for your actual file processing logic
}

void processDirectory(char *dirname, int depth) {
    DIR *directory;
    struct dirent *entry;

    if ((directory = opendir(dirname)) == NULL) {
        perror("opendir failed");
        return;
    }

    while((entry = readdir(directory)) != NULL) {
        char path[FILENAME_MAX];
        snprintf(path, sizeof(path), "%s/%s", dirname, entry->d_name);

        if (entry->d_type == DT_DIR) {
            // This is a directory, recurse into it
            if (strcmp(entry->d_name, ".", 1) && strcmp(entry->d_name, "..", 2)) {
                processDirectory(path, depth + 1);
            }
        } else {
            // This is a file, handle it
            processFile(path);
        }
    }

    closedir(directory);
}

int main() {
    processDirectory(".", 0);  // Start processing in the current directory
    return 0;
}
```
This simple program starts with the current directory and recursively processes all files within it, including those in subdirectories.

