import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.concurrent.atomic.AtomicReference;

public class Deserializer {
    private AtomicReference<ObjectMapper> objectMapperRef = new AtomicReference<>();

    public <T> T deserialize(byte[] data, Class<T> clazz) throws IOException {
        ObjectMapper mapper = objectMapperRef.get();
        if (mapper == null) {
            throw new IllegalStateException("ObjectMapper not initialized");
        }
        return mapper.readValue(new ByteArrayInputStream(data), clazz);
