2. RBAC system with dynamic configuration updates and fine-grained permissions:
```rust
use std::collections::HashMap;

pub struct Permission {
    name: String,
    allowed: bool,
}

pub struct User {
    username: String,
    role: Role,
}

impl User {
    pub fn has_permission(&self, permission: &Permission) -> bool {
        self.role.has_permission(permission)
    }
}

pub struct Role {
    name: String,
    permissions: HashMap<String, Permission>,
}

impl Role {
    pub fn has_permission(&self, permission: &Permission) -> bool {
        match self.permissions.get(permission) {
            Some(p) => p.allowed,
            None => false,
        }
    }
}
```
