#include <string.h>

int checkPasswordValidity(char* password, int len){
    if(!password || len < 8) {
        return -1; // Invalid Password
    }

    int hasUpper = 0, hasLower = 0, hasDigit = 0;

    for(int i=0; i<len; ++i){
        if(isupper(password[i])){
            hasUpper++;
        } else if(islower(password[i])) {
            hasLower++;
        } else if(isdigit(password[i])) {
            hasDigit++;
        }
