OAuth2Response* processOAuth2AccessToken(const char* response, const char* id) {

    json_error_t error;
    json_t *root = json_loads(response, 0, &error);

    if(!json_is_object(root)) {
        // handle error: malformed JSON
        return NULL;
    }

    OAuth2Response* oauthResp = (OAuth2Response*)malloc(sizeof(OAuth2Response));

    json_t *accessToken, *expiresIn, *tokenType, *refreshToken;

    // validate required fields and extract values
    accessToken = json_object_get(root, "access_token");
    if(!json_is_string(accessToken)) {
        // handle error: incorrect field type or missing field
        free(oauthResp);
        return NULL;
    }
    oauthResp->access_token = strdup(json_string_value(accessToken));

    expiresIn = json_object_get(root, "expires_in");
    if(!json_is_integer(expiresIn)) {
        // handle error: incorrect field type or missing field
        free(oauthResp->access_token);
        free(oauthResp);
        return NULL;
    }
    oauthResp->expires_in = json_integer_value(expiresIn);

    tokenType = json_object_get(root, "token_type");
