    private final BlockingQueue<SensorEvent> queue = new LinkedBlockingQueue<>();

    public void add(SensorEvent event) {
        queue.add(event);  // Adds the specified event to this queue if it is possible to do so immediately without exceeding the queue's capacity, else throws an IllegalStateException.
    }

