['Here is a sample solution using Python with asyncio, aiohttp, tenacity for resilience pattern, and some other libraries (not all are included in this sample due to space limitation). This code does not cover everything you described but gives an idea on how to structure your serverless architecture. 

```python
import json
import logging
from typing import List, Dict, Any
from tenacity import retry_if_exception_type, stop_after_attempt, wait_exponential, TryAgain
from aiohttp import ClientSession, TCPConnector
from asyncio import gather, get_event_loop
import hashlib

class ConfigurationManager:
    def __init__(self):
        # Implement the configuration manager
        pass

    def get(self, key: str) -> Any:
        # Get a specific configuration value
        pass

class LoggingHandler:
    def __init__(self):
        # Configure logging here
        self.logger = logging.getLogger('DataProcessor')

    def log_info(self, message: str) -> None:
        self.logger.info(message)

    def log_error(self, message: str) -> None:
        self.logger.error(message)

class DataProcessingPipeline:
    def __init__(self):
        # Implement the pipeline logic here
        pass

    def process(self, data: Any) -> Any:
        # Process data and return the result
        pass

@retry_if_exception_type(TryAgain)
async def fetch_data(url: str, config: ConfigurationManager, logger: LoggingHandler):
    max_attempts = config.get('MAX_RETRY')
    timeout = config.get('TIMEOUT')

    try:
        async with ClientSession(connector=TCPConnector(ssl=False), timeout=timeout) as session:
            response = await session.get(url, raise_for_status=True)
            logger.log_info(f"Fetched data from {url}")

    except Exception as e:
        logger.log_error(f'Error fetching data from {url}: {e}')

        # If we have made enough attempts, raise to stop retrying
        if max_attempts <= 0:
            raise TryAgain()
        else:
            config.update('MAX_RETRY', max_attempts - 1)

    return await response.text()

async def fetchAndProcessDataStream(urls: List[str], pipeline: DataProcessingPipeline, config: ConfigurationManager, logger: LoggingHandler):
    responses = []

    for url in urls:
        data = await fetch_data(url, config, logger)
        responses.append(pipeline.process(data))

    results = await gather(*responses)

    return json.dumps(results)
```

The function `fetchAndProcessDataStream` is an async function that fetches data from the provided URLs, processes them using the pipeline and returns the processed data in JSON format. It uses tenacity for retrying failed requests according to a retry policy defined by the configuration manager.

Please note that you need to implement more features like logging handler, config manager, pipeline etc as per your requirements. Also remember, this is just a simplified example and real implementation may be significantly different based on various factors.
