#include <openssl/evp.h>

typedef struct _crypto_ctx {
    EVP_CIPHER_CTX *encrypt, *decrypt;
} CryptoCtx;

int init(CryptoCtx *ctx, const unsigned char* key, int keylen, 
         const unsigned char* iv, const EVP_CIPHER* cipher) {
    ctx->encrypt = EVP_CIPHER_CTX_new();
    ctx->decrypt = EVP_CIPHER_CTX_new();

    EVP_EncryptInit_ex(ctx->encrypt, cipher, NULL, key, iv);
    EVP_DecryptInit_ex(ctx->decrypt, cipher, NULL, key, iv);

    return 0;
}

int update(CryptoCtx *ctx, const unsigned char* in, int inlen, unsigned char* out) {
    EVP_EncryptUpdate(ctx->encrypt, out, &outlen, in, inlen);

    return 0;
}

int finalize(CryptoCtx *ctx, unsigned char* out) {
    int outlen = 0;
    EVP_EncryptFinal_ex(ctx->encrypt, out, &outlen);

    return 0;
}
```
The above code is a simplified example of what the cryptographic library could look like. It uses OpenSSL's EVP interface for encryption and decryption. The `init` function initializes the encrypt and decrypt contexts with the given cipher and key/iv parameters. The `update` function can be used to perform multiple updates on the same input data, while the `finalize` function finishes the encryption or decryption process.
"]

