#include <stdarg.h>
#include <unistd.h>
#include <sys/wait.h>
#include <cstring>
#include <forward_list>
#include <iostream>
#include <fstream>
#include <mutex>
#include <atomic>
#include <sstream>
#include <thread>

// Log Level Definition
enum class LogLevel {
    TRACE, DEBUG, INFO, WARN, ERROR, CRITICAL
};

class Logger{
public:
   static void log(LogLevel level, const char* fmt...) {
       std::lock_guard<std::mutex> guard(_mtx);  // lock for thread-safety
       va_list args;
       va_start (args, fmt);
       char buffer[256];
       vsnprintf(buffer, sizeof(buffer), fmt, args);   // format the message
       std::cout << buffer << std::endl;     // print to console
       va_end (args);
    }
private:
   static std::mutex _mtx;  // for thread safety
};
std::mutex Logger::_mtx;

void executeShellCommandAndLog(std::forward_list<std::string>& list, const std::string& searchString, const std::string& insertionString) {
    static std::atomic<bool> isSearching{false}; // flag for preventing race condition when searching

    if (isSearching.exchange(true)) {  // try to acquire the lock, if already locked then skip this loop.
        Logger::log(LogLevel::WARN,"Another thread is currently searching. Skipping...");
        return;
    }

    auto it = std::find(list.begin(), list.end(), searchString);
    if (it == list.end()) {  // if not found, append the insertion string and continue with normal operation.
        Logger::log(LogLevel::INFO,"Inserting %s",insertionString.c_str());
        list.push_front(insertionString);
    } else {
        Logger::log(LogLevel::DEBUG, "Found: %s", it->c_str());
    }

    isSearching = false; // release the lock.
}
```

Note that handling shell commands and executing them via child processes in a web environment would involve JavaScript (node.js), not C++ or even a compiled language, as there's no way to interact directly with the shell from the browser sandbox, due to security restrictions. 

