from flask import Flask, request, jsonify
from pymongo import MongoClient
from bson.json_util import dumps
import logging

app = Flask(__name__)
client = MongoClient('mongodb://localhost:27017/')  # Assuming that MongoDB is running on local machine
db = client['sensorData']
collection = db['sensorCollection']

@app.route('/api/v1/data', methods=['GET'])
def get_data():
    try:
        args = request.args
        start_time = args.get('startTime') if 'startTime' in args else None
        end_time = args.get('endTime') if 'endTime' in args else None
        sensorId = args.get('sensorId') if 'sensorId' in args else None
        condition = args.get('condition') if 'condition' in args else None

        query_filter = {}
        if start_time and end_time:
            query_filter['timestamp'] = {'$gte': start_time, '$lt': end_time}
        if sensorId:
            query_filter['sensorId'] = sensorId
        if condition:
            query_filter['condition'] = condition

        data = collection.find(query_filter)
        return dumps(data), 200, {'ContentType':'application/json'}
    except Exception as e:
        logging.error("An error occurred", exc_info=True)
        return jsonify({"error": "Internal Server Error"}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

This code snippet provides a basic RESTful API endpoint `/api/v1/data` which retrieves data based on the provided query parameters such as startTime, endTime, sensorId and condition. It utilizes Flask to handle HTTP requests and MongoDB for storing and retrieving time-series sensor data. 

