const rateLimiter = new RateLimiterRedis({
    storeClient: redisClient,
    points: 10, // Number of requests per second
    duration: 1,
});

class MetadataService {
    private cache = {};
    private fallbackDB;

    constructor(fallbackDB) {
        this.fallbackDB = fallbackDB;
    }

    async getMetadata(id: string): Promise<any> {
        if (this.cache[id]) return this.cache[id];

        try {
            await rateLimiter.consume(); // Apply rate limiting 

            const response = await asyncRetry(() => axios.get(`https://api.example.com/metadata?id=${id}`), {retries: 5});

            this.cache[id] = response.data;

            return response.data;
        } catch (err) {
            if ((err as AxiosError).response?.status === 429) console.log(`Too many requests to API for id: ${id}`);
            else console.error(`Failed to get metadata for id: ${id}. Error: ${err}`);

            return this.fallbackDB[id] || null; // Fall back to local database if available
        }
    }

    async updateMetadata(id: string, data: any) {
        try {
            await axios.post('https://api.example.com/metadata', {id, data});

            this.cache[id] = data; // Update cache
        } catch (err) {
            console.error(`Failed to update metadata for id: ${id}. Error: ${err}`);
        }
    }

    async processDOMElement(elementId: string, metadataId: string) {
        const metadata = await this.getMetadata(metadataId);

        // Process DOM element with the retrieved metadata... 
    }
}

const app = express();
app.use(express.json());

app.post('/update-dom', async (req, res) => {
    const {elementId, metadataId} = req.body;

    const serviceInstance = new MetadataService({/* Fallback DB data */});
