```C
#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>

// This semaphore would be initialized with a value from your centralized configuration service.
sem_t scriptSem; 

void *loadAndExecuteScripts(void* arg) {
    char* file = (char*)arg;

    // Acquire the semaphore before proceeding to ensure thread safety.
    sem_wait(&scriptSem);  

    printf("Loading and executing script: %s\n", file);

    /* Loading and execution of scripts logic goes here */ 

    sem_post(&scriptSem); // Release the semaphore after finishing with resources.
}

int main() {
    const char* files[] = {"script1.js", "script2.js", "script3.js"};

    if (sem_init(&scriptSem, 0, /* Initial value from configuration service */) == -1) {
        perror("Failed to initialize semaphore");
        return 1;
    }

    pthread_t threads[sizeof(files)/sizeof(char*)];

    for (int i = 0; i < sizeof(files)/sizeof(char*); ++i) {
        // Create a new thread to handle each script file concurrently.
        if (pthread_create(&threads[i], NULL, loadAndExecuteScripts, (void*)files[i]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < sizeof(files)/sizeof(char*); ++i) {
        // Join all threads after they have completed their work.
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return 1;
        }
    }

    sem_destroy(&scriptSem); // Destroy the semaphore after use.

    return 0;
}
```
