int main(int argc, char* argv[]) {
    av_log_set_level(AV_LOG_INFO); // Set FFmpeg log level to INFO

    if (argc != 3) {
        std::cerr << "Usage: ./app <input_dir> <output_dir>\n";
        return 1;
    }

    fs::path inputDir = argv[1];
    fs::path outputDir = argv[2];

    if (!fs::is_directory(inputDir)) {
        std::cerr << "Input directory does not exist\n";
        return 1;
    }

    if (!fs::exists(outputDir)) {
        fs::create_directories(outputDir);
    } else if (!fs::is_directory(outputDir)) {
        std::cerr << "Output directory exists and is not a directory\n";
        return 1;
    }

    // Iterate over files in input directory
    for (const auto& entry : fs::directory_iterator(inputDir)) {
        if (!fs::is_regular_file(entry.status())) continue; // Skip non-files

        std::string filename = entry.path().filename();
        std::string inputFilePath = inputDir / filename;
        std::string outputFilePath = (outputDir / filename).replace_extension(".mp4"); // Change extension to .mp4 for example

        AVFormatContext* inputContext = nullptr;
        if (avformat_open_input(&inputContext, inputFilePath.c_str(), nullptr, nullptr) != 0) {
            std::cerr << "Failed to open input file: " << filename << '\n';
            continue;
        }

        // ... rest of the code to process file goes here ...
    }

    return 0;
}
