        if (is_valid(conn)) {
            std::unique_lock<std::shared_mutex> lock(mtx_);

            // If we've hit our limit, just drop this connection instead of adding it back into the pool.
            if (available_ < pool_.size()) {
                pool_[--available_] = std::move(conn);  // Move conn to available position in the pool.
            }

