        {
            var apiToUse = loadBalancer.GetNextAPI(externalAPIs);

            var policy = Policy
                .Handle<Exception>()
                .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

