int IntegerProcessor_process(IntegerProcessor *ip) {
    int largest = 0;
    char buf[256];
    ssize_t nread;
    size_t entries_count = 0;

    while ((nread = read(ip->fd, buf, sizeof(buf))) > 0) {
        for (int i = 0; i < nread; ++i) {
            if (isdigit((unsigned char)buf[i])) {
                int number = strtol(&buf[i], NULL, 10);
                if (number > largest) {
                    largest = number;
                }
                ++entries_count;
                if(ip->max_entries != 0 && entries_count >= ip->max_entries){
                    break;
                }
            } else if (!isspace((unsigned char)buf[i])) {
                /* If logging is enabled */
                if (ip->log_level > 1) {
                    fprintf(stderr, "Invalid character in input: %c\n", buf[i]);
                }
            }
        }
    }

    return largest;
}
