['Here is an example of how you could implement this using ADO.NET and System.Data.SqlClient for sending a byte array to a SQL Server database server. This code does not cover all aspects of your problem, but it should give you a starting point.

```csharp
using System;
using System.IO;
using System.Data;
using System.Data.SqlClient;

public class DatabaseManager
{
    private readonly string _connectionString;

    public DatabaseManager(string connectionString)
    {
        _connectionString = connectionString;
    }

    public DataTableReader ExecuteQuery(byte[] queryBytes, SqlParameter[] parameters = null)
    {
        using (var conn = new SqlConnection(_connectionString))
        {
            using (var cmd = new SqlCommand())
            {
                cmd.Connection = conn;

                // Convert byte array to string for SQL command text
                var queryText = System.Text.Encoding.UTF8.GetString(queryBytes);
                cmd.CommandText = queryText;

                if (parameters != null)
                {
                    foreach (var param in parameters)
                    {
                        cmd.Parameters.Add(param);
                    }
                }

                conn.Open();
                var reader = cmd.ExecuteReader(CommandBehavior.CloseConnection);

                return reader;
            }
        }
    }
}
```

This class takes a connection string, a byte array representing the SQL command to be executed and an optional collection of parameters for the SQL query. The method `ExecuteQuery` opens a connection to the database, executes the SQL command using the provided parameters (if any), then returns a DataTableReader which can be used to iterate over the result set.

Please note that this is a simplified version and does not cover all aspects of your problem such as encryption for secure transmission of the query bytes or the handling of potential failures, but it should give you a starting point. Also, make sure to validate any input to prevent SQL injection attacks and other issues.
