    std::time_t now = std::time(nullptr);
    va_list args;
    va_start (args, format);
    std::string timeStr(std::ctime(&now));  // add a newline character
    timeStr.pop_back();  // remove the trailing newline character

    char buffer[256];
    vsnprintf (buffer, sizeof(buffer), format, args);
    va_end (args);

    std::cout << "["<<timeStr<<"] - ["<<logLevelToString(level)<<"]: " << buffer << std::endl;  // log to console

    std::ofstream file("log.txt", std::ios_base::app | std::ios_base::out);   // open the log file for appending and writing
    file << "["<<timeStr<<"] - ["<<logLevelToString(level)<<"]: " << buffer << std::endl;  // log to file
}
```
Please ensure that `logLevelToString` is a function that converts the `LOG_LEVEL` enum value to its corresponding string representation.

