    root = json_loads(jsonString, 0, &error);

    if(!root) {
        printf("Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return token;
    }
    // Extract values from JSON object and validate

    json_t *access_token, *expires_in, *token_type, *refresh_token;

    json_unpack(root, "{s:s, s:i, s?:s, s?:s}", 
                "access_token", &token.access_token, 
                "expires_in", &token.expires_in,
                "token_type", &token.token_type,
                "refresh_token", &token.refresh_token);

    if(!validate(&token)) {
        printf("Invalid token\n");
    }

    json_decref(root);  // Decrease reference count and free up memory
    return token;
}
```

