touch server.js .env
```

2. Server setup: 

Create a `server.js` file with the following content:

```javascript
require('dotenv').config();
const express = require('express');
const morgan = require('morgan');
const bodyParser = require('body-parser');
const cors = require('cors');
const helmet = require('helmet');

// import routes
const uploadRoute = require('./routes/upload');
const userRoutes = require('./routes/user');

const app = express();
app.use(morgan('dev'));
app.use(bodyParser.urlencoded({ extended: false }));
app.use(bodyParser.json());
app.use(cors());
app.use(helmet());

// use routes
app.use('/upload', uploadRoute);
app.use('/user', userRoutes);

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server running on port ${port}`));
```

3. Create `routes/upload.js`:

```javascript
const express = require('express');
const router = express.Router();
const multer = require('multer');
const checkAuth = require('../middleware/check-auth');

// Setup Multer for file uploads
const storage = multer.diskStorage({
  destination: function(req, file, cb) {
    cb(null, './uploads/');
  },
  filename: function(req, file, cb) {
    cb(null, new Date().toISOString() + file.originalname);
  }
});
const upload = multer({ storage: storage });

router.post('/', checkAuth, upload.single('file'), (req, res) => {
  // handle the uploaded file and save it to a database or CDN here
  res.status(201).json({ message: 'File Uploaded!' });
});

module.exports = router;
```

4. Create `routes/user.js`:

```javascript
const express = require('express');
const router = express.Router();

// import User model and necessary middleware

router.post('/signup', (req, res) => {
  // handle user sign up here
});

router.post('/login', (req, res) => {
  // handle user login here
});

module.exports = router;
```

5. Create `middleware/check-auth.js`:

```javascript
const jwt = require('jsonwebtoken');

module.exports = (req, res, next) => {
  try {
    const token = req.headers.authorization.split(" ")[1];
    const decoded = jwt.verify(token, process.env.JWT_KEY);
    req.userData = decoded;
    next();
  } catch (error) {
    return res.status(401).json({
      message: 'Auth failed'
    });
  }
};
```

This is a basic setup for the REST API service. You would need to add more routes, middleware and models according to your requirements. Also, this does not include setting up a database or cloud storage integration. 

Please note that creating such a system is a large task that requires careful planning and testing. It's recommended to split the project into smaller tasks and tackle each one at a time, testing thoroughly after implementing each feature to ensure everything works as expected before moving on to the next one.
']

