        new ConcurrentDictionary<string, ImageMetadata>();

    public async Task<Bitmap> ProcessImageAsync(string imagePath)
    {
        var policy = Policy
            .Handle<Exception>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        Bitmap processedImage;
        try 
        {
            // Try to get image from cache
            if (_imageCache.TryGetValue(imagePath, out var cachedImage)) 
            {
                processedImage = cachedImage;
            } 
            else 
            {
                // Load the image from disk (or wherever it's stored)
                Image originalImage = Image.FromFile(imagePath);

                // Apply filters and transformations based on metadata
                ImageMetadata metadata = await policy.ExecuteAsync(async () => await _metadataService.GetMetadataAsync(imagePath));

                processedImage = ApplyTransforms(originalImage, metadata);

                // Cache the processed image for future use
                _imageCache[imagePath] = processedImage;
            }
        } 
        catch (Exception ex) 
        {
            Console.WriteLine("Error processing image: " + ex.Message);
            throw;
        }

        return processedImage;
    }

