```csharp
public class AggregationService : IAggregationService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _distributedCache;

    public AggregationService(HttpClient httpClient, IDistributedCache distributedCache)
    {
        _httpClient = httpClient;
        _distributedCache = distributedCache;
    }

    public async Task<string> ComputeHashAsync(IEnumerable<int> integers)
    {
        var hashBytes = await _distributedCache.GetOrAddAsync("aggregated_hash", () => ComputeAndStoreAggregateHash(integers));

        return Convert.ToBase64String(hashBytes);
    }

    private async Task<byte[]> ComputeAndStoreAggregateHash(IEnumerable<int> integers)
    {
        var hashAlgorithm = MD5.Create();
        var hash = await hashAlgorithm.ComputeHashAsync(integers.ToArray());

        // Store the computed hash in cache for future use
        await _distributedCache.SetAsync("aggregated_hash", hash);

        return hash;
    }
}

public class AggregationController : ControllerBase
{
    private readonly IAggregationService _service;

    public AggregationController(IAggregationService service)
    {
        _service = service;
    }

    [HttpPost("upload")]
    public async Task<ActionResult> UploadIntegers([FromBody] int[] integers)
    {
        if (integers == null || !integers.Any())
            return BadRequest();

        var hash = await _service.ComputeHashAsync(integers);

        // Save the hash to a database or similar here

        return Ok(hash);
    }
}
```
