    private SchemaRegistry schemaRegistry;
    private ThirdPartyConfigTool thirdPartyConfigTool;

    // Some cache mechanism, e.g., Guava Cache or Ehcache
    private LoadingCache<String, Serializer> serializerCache;

    public SerializationUtility(SchemaRegistry schemaRegistry, 
            ThirdPartyConfigTool thirdPartyConfigTool) {
        this.schemaRegistry = schemaRegistry;
        this.thirdPartyConfigTool = thirdPartyConfigTool;

        // Initialize the cache here with appropriate configuration
    }

    public <T> T deserialize(byte[] data, Class<T> clazz) throws SerializationException {

        String schemaId = schemaRegistry.getSchemaIdForClass(clazz);
        Serializer serializer = null;

        try {
            // Try to get the serializer from cache
            serializer = serializerCache.get(schemaId);
        } catch (ExecutionException e) {
            throw new SerializationException("Failed to deserialize", e);
        }

        if (serializer == null) {
            // If not found in cache, get it from schema registry and update the cache
            serializer = thirdPartyConfigTool.getSerializerForSchema(schemaId);
            serializerCache.put(schemaId, serializer);
        }

        try {
            return (T) serializer.deserialize(data);
        } catch (SerializationException e) {
            throw new SerializationException("Failed to deserialize", e);
        }
    }

    // Handle version mismatches, cache management, concurrency etc. would go here. 
}
