```java
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

public abstract class AbstractModelFactory {
    private static final Logger LOGGER = LoggerFactory.getLogger(AbstractModelFactory.class);

    private Map<String, Function<String, Object>> factoryRegistry = new HashMap<>();
    private ObjectMapper mapper = new ObjectMapper();

    public synchronized void registerFunction(String id, Class<?> clazz) {
        Function<String, Object> function = json -> {
            try {
                return mapper.readValue(json, clazz);
            } catch (IOException e) {
                LOGGER.error("Failed to deserialize JSON: " + json, e);
                throw new RuntimeException(e); // Handle this how you see fit
            }
        };

        factoryRegistry.put(id, function);
    }

    public synchronized Object createInstanceFromJson(String id, String json) {
        if (!factoryRegistry.containsKey(id)) {
            throw new IllegalArgumentException("No factory registered for ID: " + id);
        }

        return factoryRegistry.get(id).apply(json);
    }
}
```
