['Creating an encryption service in C with all these features would require complex code structure and design, which can't be done within few lines of text due to complexity. However, I will give you a simple example of how to implement AES encryption using OpenSSL library in C. Here is the base skeleton for your code:

```c
#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>

void handleErrors(void) { /* Error handling function */ }

int do_crypt(FILE *in, FILE *out, int do_encrypt) {
    unsigned char inbuf[1024], outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
    int inlen, outlen;
    EVP_CIPHER_CTX *ctx;

    /* Create and initialise the context */
    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv, do_encrypt);

    for (;;) {
        inlen = fread(inbuf, 1, 1024, in);
        if (inlen <= 0) break; /* EOF */
        if (!EVP_CipherUpdate(ctx, outbuf, &outlen, inbuf, inlen)) handleErrors();
        fwrite(outbuf, 1, outlen, out);
    }

    if (!EVP_CipherFinal_ex(ctx, outbuf, &outlen)) handleErrors();
    fwrite(outbuf, 1, outlen, out);

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int main(int argc, char *argv[]) {
    FILE *infile, *outfile;

    infile = fopen("input.txt", "rb");
    outfile = fopen("output.txt", "wb");

    do_crypt(infile, outfile, 1); /* Encryption */
    //do_crypt(infile, outfile, 0); /* Decryption */

    return 0;
}
```

