["Here is a high-level outline of how you can implement this in Python using Flask for API gateway, Gunicorn as application server and NGINX as reverse proxy. Note that implementing all these details will be quite lengthy and complex task. 

```python
from flask import Flask, request, jsonify
import requests
from functools import wraps
import time

app = Flask(__name__)

# Define rate limit constants
MAX_REQUESTS = 5000
TIME_WINDOW = 60  # seconds
request_timestamps = []

def validate_token(func):
    @wraps(func)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Missing Authorization header'}), 403

        # Make a call to OAuth2 server for token validation
        response = requests.post('http://oauth-server/validate', headers={'Authorization': token})
        if not response.ok:
            return jsonify({'message': 'Invalid or expired token'}), 403

        return func(*args, **kwargs)
    return decorated

def rate_limit(func):
    @wraps(func)
    def decorated(*args, **kwargs):
        now = time.time()
        request_timestamps.append(now)
        while request_timestamps[0] < (now - TIME_WINDOW):  # Remove old requests
            request_timestamps.pop(0)

        if len(request_timestamps) > MAX_REQUESTS:
            return jsonify({'message': 'Rate limit exceeded, try again later'}), 429

        return func(*args, **kwargs)
    return decorated

@app.route('/product', methods=['GET', 'POST', 'PUT', 'DELETE'])
@validate_token
@rate_limit
def product():
    # Implement request routing and processing logic here
```

Please note that the above is just a basic example of how to set up a rate limit for requests. For real-world applications, it's advisable to use more advanced strategies like token bucket or leaky bucket algorithm.
