```javascript
const fetch = require('node-fetch');
const Bottleneck = require("bottleneck");
const limiter = new Bottleneck({
  reservoir: 20, // ensure no more than 20 jobs are running at any point in time
  reservoirRefreshAmount: 20,
  reservoirRefreshInterval: 60 * 1000,
  maxConcurrent: 5 // no more than 5 requests running at the same time
});

class DataIngestor {
    constructor(sources) {
        this.sources = sources;
    }

    async fetchDataFromSource(source) {
        let retries = 3;
        while (retries-- > 0) {
            try {
                const res = await limiter.schedule(() => fetch(source));

                if (!res.ok) throw new Error('HTTP error ' + res.status);
                return await res.json();
            } catch (err) {
                console.error(`Error while fetching data from source ${source}: `, err);
                if (retries === 0) {
                    // Override mechanism goes here 
                } else {
                    // Exponential backoff logic goes here
                    await new Promise(resolve => setTimeout(resolve, Math.pow(2, 3 - retries) * 1000));
                }
            }
        }
    }

    async ingestData() {
        const promises = this.sources.map(source => this.fetchDataFromSource(source));

        try {
            // Wait for all the sources to be fetched and process them asynchronously
            const results = await Promise.allSettled(promises);

            // Process results here...
            console.log('Results: ', results);
        } catch (err) {
            console.error('Error while ingesting data: ', err);
        }
    }
}
```

For buffering and logging, you might want to consider using libraries like `async` for concurrency control or `winston` for logging. For testing, you can use tools such as Jest or Mocha. Please make sure to include proper documentation for your code along with comments explaining complex logic.
