void TaskManager::removeTask(int taskId) {
    tasks.erase(std::remove_if(tasks.begin(), tasks.end(), [&](const std::shared_ptr<Task>& t){return t->getId() == taskId;}), tasks.end());
}

void TaskManager::updatePriority(int taskId, int newPriority) {
    auto it = std::find_if(tasks.begin(), tasks.end(), [&](const std::shared_ptr<Task>& t){return t->getId() == taskId;});
