However, I will provide an example of how such a function could look like:

```C
#include <stdio.h>
#include <string.h>
#include <jansson.h> /* JSON parsing library */

bool validate_token(const char *json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return false;
    }

    json_t *access_token, *expires_in, *token_type, *refresh_token = NULL;

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");

    /* Check for optional fields */
    if(!json_is_null(json_object_get(root, "refresh_token"))) {
        refresh_token = json_object_get(root, "refresh_token");
    }

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || 
       !json_is_string(token_type) || (refresh_token && !json_is_string(refresh_token))) {
        fprintf(stderr, "Invalid token format.\n");
        json_decref(root);
        return false;
    }

    if(strcmp(json_string_value(token_type), "Bearer") != 0) {
        fprintf(stderr, "Invalid token type. Expected 'Bearer', got '%s'.\n", json_string_value(token_type));
        json_decref(root);
        return false;
    }

    json_decref(root);
    return true;
}
```
This function uses the Jansson library to parse JSON, and checks if all required fields (`access_token`, `expires_in`, `token_type`) exist and have correct types. The function returns `false` if any of the checks fail, and prints a detailed error message otherwise.
']

["This task requires a more complex setup than would be practical in a simple code snippet. However, here's a simplified example of how one might begin to approach this problem using C language with POSIX threads (pthread) for synchronization and atomic operations. Please note that you will need a proper database API to interact with your signaling database, the network operator APIs would also require actual implementations, these have been omitted for simplicity:

```c
#include <pthread.h>
#include <stdatomic.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int ue_id;
    atomic_int signal_strength;
    atomic_int snr;
    time_t timestamp;
} UESessionState;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
UESessionState *sessions = NULL;
size_t session_count = 0;

void addSession(int ue_id, int signal_strength, int snr) {
    pthread_mutex_lock(&lock);
    sessions = realloc(sessions, (session_count + 1) * sizeof(*sessions));
    sessions[session_count].ue_id = ue_id;
    atomic_init(&sessions[session_count].signal_strength, signal_strength);
    atomic_init(&sessions[session_count].snr, snr);
    time(&sessions[session_count].timestamp);
    session_count++;
    pthread_mutex_unlock(&lock);
}

UESessionState *getSession(int ue_id) {
    for (size_t i = 0; i < session_count; ++i) {
        if (sessions[i].ue_id == ue_id) {
            return &sessions[i];
        }
    }
    return NULL;
}

void updateSession(UESessionState *session, int new_signal_strength, int new_snr) {
    atomic_store(&session->signal_strength, new_signal_strength);
    atomic_store(&session->snr, new_snr);
    time(&session->timestamp);
}
```

