['Here is a code implementation in C++17:

```cpp
#include <algorithm>
#include <forward_list>
#include <memory>
#include <mutex>
#include <optional>
#include <shared_mutex>
#include <string>
#include <glog/logging.h> // Google Logging Library (GLOG) for logging

// Global lock for managing access to the forward list.
std::shared_timed_mutex gMutex; 

std::optional<bool> insertAfterFirstOccurrence(const std::shared_ptr<std::forward_list<std::string>>& flist, const std::string& target, const std::string& toInsert) {
    // Lock the list for reading.
    std::shared_lock<std::shared_timed_mutex> lock(gMutex); 

    auto it = std::find(flist->begin(), flist->end(), target);
    if (it != flist->end()) {
        // Lock the list for writing.
        lock.unlock();
        std::lock_guard<std::shared_timed_mutex> writeLock(gMutex); 
        ++it; // Move to next element so we can insert after it.
        try {
            flist->insert_after(it, toInsert);
        } catch (const std::bad_alloc& e) {
            LOG(ERROR) << "Memory allocation error: " << e.what(); 
            return std::nullopt; // Return nullopt in case of memory allocation failure.
        }
    } else {
        lock.unlock();
        std::lock_guard<std::shared_timed_mutex> writeLock(gMutex); 
        try {
            flist->push_back(toInsert); // Append to end if target not found.
        } catch (const std::bad_alloc& e) {
            LOG(ERROR) << "Memory allocation error: " << e.what();
            return std::nullopt; 
        }
    }

    LOG(INFO) << "Successfully inserted '" << toInsert << "' after first occurrence of '" << target << "'.";
    return true; // Return true if insertion was successful.
}
```
Please note that this is a high-level implementation and might need additional error handling for production grade code. 
Also, profiling and performance optimization would be required based on actual use case as it may vary between different systems/applications. Also remember to initialize the Google Logging library before using it in your application. 
For unit testing, you could use a framework such as Google Test, which provides features for setting up test fixtures and running multiple tests concurrently.
Lastly, please note that shared_timed_mutex doesn't exist until C++20 standard so make sure to replace it with the appropriate library/built-in threading mechanisms if you are using a lower version of C++.
']

