```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Instant;

// Structure to store parent and rank of each node
pub struct Node {
    pub parent: Arc<Mutex<Node>>,
    pub rank: usize,
}

impl Node {
    fn new(repr: i32) -> Arc<Mutex<Self>> {
        let mut n = Self {
            parent:Arc::new(Mutex::new(Node{parent:Arc::new(Mutex::new(Node{parent:Arc::new(Mutex::new(Node{
                parent:Arc::new(Mutex::new((*Self).clone())),
                rank:0,
            })))),rank:1}))),
            rank: 0,
        };
        n.parent = Arc::new(Mutex::new(n));
        Arc::new(Mutex::new(n))
    }
}

// Structure to store disjoint sets and perform operations
pub struct DisjointSet {
    nodes: HashMap<i32, Arc<Mutex<Node>>>,
}

impl DisjointSet {
    pub fn new() -> Self {
        Self {
            nodes: HashMap::new(),
        }
    }

    pub async fn find(&self, mut x: i32) -> Arc<Mutex<Node>>{
        let node = self.nodes.get_mut(&x).unwrap();
        if (*node).parent == *node {
            return *node;
        } else {
            (*node).parent = Self::find(self, x);
            return (*node).parent;
        }
    }

    // ... Implementation of union and other operations goes here. These would involve locking the nodes for concurrent access ...
}
```

