    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

PGconn *conn = NULL; // Global database connection

int process_and_store_crc_indications(NFAPI_CRC_INDICATION_PDU_T* arr, int n) {
    if (n <= 0 || arr == NULL) return 0;

    PGresult *res;
    char sql[256];

    atomic_flag lock = ATOMIC_FLAG_INIT; // Initialize lock

    while(atomic_flag_test_and_set(&lock)); // Lock the function

    conn = PQconnectdb("user=your_username dbname=your_database");

    for (int i = 0; i < n; ++i) {
        if (PQstatus(conn) != CONNECTION_OK) {
            printf("Connection to database failed: %s", PQerrorMessage(conn));
            PQfinish(conn); // Close connection
            atomic_flag_clear(&lock); // Release the lock before returning
            return -1;
        }

        sprintf(sql, "INSERT INTO your_table (RNTI) VALUES (%d)", arr[i].RNTI);
        res = PQexec(conn, sql);

        if (PQresultStatus(res) != PGRES_COMMAND_OK) {
            printf("INSERT failed: %s", PQerrorMessage(conn));
            PQclear(res); // Clear result
            atomic_flag_clear(&lock); // Release the lock before returning
            return -1;
        }

        PQclear(res); // Clear result
    }

    PQfinish(conn); // Close connection
    atomic_flag_clear(&lock); // Release the lock

    return 0;
}
