public class MiddlewareComponent : BackgroundService
{
    private readonly KafkaConsumer _kafkaConsumer;
    private readonly CloudStorage _cloudStorage;
    private readonly ExternalDependency _externalDependency;
    private readonly LoggingMonitoringSystem _loggingMonitoring;
    private readonly DeduplicationCache _dedupCache;
    private readonly RetryPolicy _retryPolicy;

    public MiddlewareComponent(
        KafkaConsumer kafkaConsumer, 
        CloudStorage cloudStorage, 
        ExternalDependency externalDependency, 
        LoggingMonitoringSystem loggingMonitoring,
        DeduplicationCache dedupCache,
        RetryPolicy retryPolicy)
    {
        _kafkaConsumer = kafkaConsumer;
        _cloudStorage = cloudStorage;
        _externalDependency = externalDependency;
        _loggingMonitoring = loggingMonitoring;
        _dedupCache = dedupCache;
        _retryPolicy = retryPolicy;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            var events = await _kafkaConsumer.ConsumeEventsAsync();

            foreach (var @event in events)
            {
                if (_dedupCache.TryAdd(@event)) 
                {
                    try
                    {
                        // Process event with retry policy
                        var processedEvent = await _retryPolicy.ExecuteAsync(async () =>
                            await _externalDependency.ProcessEventAsync(@event));

                        // Persist to cloud storage with retry policy
                        await _retryPolicy.ExecuteAsync(async () => 
                            await _cloudStorage.PersistEventAsync(processedEvent));
                    }
                    catch (Exception ex) 
                    { 
                        _loggingMonitoring.LogError("Failed to process event", ex); 
                    }
                }
            }
        }
    }
}
