```c
#include <stdio.h>
#include <libpq-fe.h>

void process_and_store_crc_indications(NFAPI_CRC_INDICATION_PDU_T* indications, int size) {
    PGconn *conn = PQconnectdb("user=postgres password=secret dbname=test");

    if (PQstatus(conn) == CONNECTION_BAD) {
       fprintf(stderr, "Connection to database failed: %s\n",
            PQerrorMessage(conn));
        closeConn(conn);
        return;
    }

    for(int i=0; i<size; i++) {
        char query[256];
        sprintf(query, "INSERT INTO crc_table VALUES (%d)", indications[i].RNTI);

        PGresult *res = PQexec(conn, query);

        if (PQresultStatus(res) != PGRES_COMMAND_OK) {
            fprintf(stderr, "INSERT failed: %s", PQerrorMessage(conn));
            PQclear(res);
            closeConn(conn);
            return;
        }

        PQclear(res);
    }

    PQfinish(conn);
}
```
