class Pipeline {
public:
    void addSource(DataSource* source){ sources_.push_back(source); }
    void setTransformationEngine(TransformationEngine* engine) { transformationEngine_ = engine; }
    void addSink(DataSink* sink){ sinks_.push_back(sink); }
    void run();
private:
    std::vector<DataSource*> sources_;
    TransformationEngine* transformationEngine_;
    std::vector<DataSink*> sinks_;
};

// Actual implementation of Pipeline would require scheduling, resource management, 
// error handling and recovery logic. Also it's not thread-safe, it needs to be made thread safe by using locks etc..
void Pipeline::run(){
    for (auto source : sources_){
        source->start();
    }

    while(true) { // Continuous running pipeline
       std::vector<Data> batch = source->getBatchOfData();
       transformationEngine_->process(batch); 
       for( auto sink: sinks_) {
           sink->send(batch);
       }
    }
}
```
