['```c
#include <pthread.h>
#include <stdlib.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** ue_info = NULL;
size_t ue_count = 0;
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

void init() {
    ue_info = (NFAPI_CRC_INDICATION_PDU_T**)calloc(50000, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
}

int create_new_ue() {
    pthread_rwlock_wrlock(&lock);

    if (ue_count >= 50000) {
        pthread_rwlock_unlock(&lock);
        return -1; // Return error code when UE limit is reached.
    }

    ue_info[ue_count] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int new_ue_id = ue_count++;

    pthread_rwlock_unlock(&lock);
    return new_ue_id; // Return the ID of the newly created UE.
}

NFAPI_CRC_INDICATION_PDU_T* get_ue(int id) {
    if (id < 0 || id >= 50000) {
        return NULL; // Return error code when invalid UE ID is requested.
    }

    pthread_rwlock_rdlock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* ue = ue_info[id];
    pthread_rwlock_unlock(&lock);

    return ue; // Return the requested UE.
}

void update_ue(int id, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (id < 0 || id >= 50000) {
        return; // Return error code when invalid UE ID is requested.
    }

    pthread_rwlock_wrlock(&lock);
    ue_info[id]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    ue_info[id]->RNTI = RNTI;
    ue_info[id]->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pthread_rwlock_unlock(&lock);
}

void delete_ue(int id) {
    if (id < 0 || id >= 50000) {
        return; // Return error code when invalid UE ID is requested.
    }

    pthread_rwlock_wrlock(&lock);
    free(ue_info[id]);
    ue_info[id] = NULL;
    --ue_count;
    pthread_rwlock_unlock(&lock);
}
```
