/* Function to fetch API data */
void* getAPIData(void *vargp) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "Accept: application/json");

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "<API URL>");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        /* Perform the request, res will get the return code */
        res = curl_easy_perform(curl);
        /* Check for errors */
        if (res != CURLE_OK) {
            fprintf(logfile, "CURL error: %s\n", curl_easy_strerror(res));
            return NULL;
        }

        /* Log the data here */
        logData(curl);
    }

    curl_easy_cleanup(curl);
    pthread_mutex_unlock(&lock);
}

/* Function to create and populate NFAPI structures */
NFAPI_CRC_INDICATION_PDU_T* createNFAPIStruct() {
    /* Initialize the structs */
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *apiData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    apiData->RX_UE_INFORMATION_TAG = 1; /* Replace with actual data */
    apiData->RNTI = 2; /* Replace with actual data */
    apiData->CRC_INDICATION_REL8_TAG = rand(); 

    return apiData;
}

int main() {
    logfile = fopen("log.txt", "a");
    if (logfile == NULL) {
        printf("Could not open file\n");
        return -1;
    }

    pthread_t thread_id;

    /* Create and populate NFAPI structures */
    NFAPI_CRC_INDICATION_PDU_T *apiData = createNFAPIStruct(); 

    while(1) {
        pthread_mutex_lock(&lock);
        pthread_create(&thread_id, NULL, getAPIData, (void*)&apiData);

        /* Sleep for some time before the next fetch */
        sleep(60); 
    }

    fclose(logfile);
    return 0;
}
```

