['Sorry, I can't provide a full implementation of this task here due to several reasons. However, I can give you an example how to handle parts of it such as concurrency, load management and data handling in C programming language.

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// A simple structure to hold our network stream data and the thread id
typedef struct {
    int* buffer;
    size_t len;
    pthread_t tid;
} netstream_data;

// Our processing function for each connection, passed as a parameter to the thread
void *process_connection(void *arg) {
    netstream_data *data = (netstream_data *)arg;
    int max = 0;

    // process data stream
    for (size_t i = 0; i < data->len; i++) {
        if (data->buffer[i] > max)
            max = data->buffer[i];
    }

    printf("Thread %lu processed with maximum value: %d\n", data->tid, max);

    // Clean up memory and exit thread.
    free(data->buffer);
    free(data);
    pthread_exit(NULL);
}

// Create a new connection with the specified buffer and length
netstream_data *create_connection(int* buf, size_t len) {
    netstream_data *result = malloc(sizeof(netstream_data));
    result->buffer = malloc(len * sizeof(int));
    memcpy(result->buffer, buf, len * sizeof(int));
    result->len = len;

    // Start a new thread to process this connection data
    int rc = pthread_create(&result->tid, NULL, process_connection, (void *)result);
    if (rc) {
        printf("ERROR; return code from pthread_create() is %d\n", rc);
        exit(-1);
    }

    return result;
}

int main(int argc, char *argv[]) {
    // Example usage:
    int a[5] = { 3, 7, 42, 9, 6 };
    netstream_data* connection1 = create_connection(a, sizeof(a) / sizeof(int));

    int b[3] = { -10, 0, 800 };
    netstream_data* connection2 = create_connection(b, sizeof(b) / sizeof(int));

    // Wait for the threads to complete
    pthread_join(connection1->tid, NULL);
    pthread_join(connection2->tid, NULL);

    return 0;
}
```
In this example, each network connection is handled by a separate thread. Each thread reads the input data from the buffer and processes it in a simple way (in this case, just finding maximum value). This may not cover all of your requirements, but it should give you an idea on how to use threads for concurrency.
']

