    @PostMapping("/payments")
    @Transactional(rollbackOn = Exception.class)
    public PaymentResponse makePayment(@RequestBody Payment payment, 
                                       @RequestHeader("Authorization") String token) {
        User user = userService.getUserFromToken(token);
        // Call payment service and handle errors
        try{
            return paymentService.processPayment(user, payment);
        } catch (Exception e) {
            // Use fallback strategy if primary fails
            return fallbackPaymentStrategy.handleFallback(user, payment);
        }
    }
}

@Service
public class PaymentServiceImpl implements PaymentService{

    @Autowired
    private RestTemplate restTemplate; // To make external service calls

    @Value("${primaryPaymentGateway.url}")
    private String primaryPaymentUrl; 

    // This method handles the primary payment gateway call
    public PaymentResponse processPayment(User user, Payment payment){
        ResponseEntity<String> response = restTemplate.postForEntity(primaryPaymentUrl + "/payments", payment, String.class);
        if (response.getStatusCode().is2xxSuccessful()){
            return objectMapper.readValue(response.getBody(), PaymentResponse.class);
        } else {
            throw new RuntimeException("Error processing payment");
        }
    }
}
