function copyBytes(bufferList, bytesToCopy) {
    let totalLength = bufferList.reduce((total, buf) => total + buf.length, 0);

    if (bytesToCopy > totalLength) {
        throw new Error('Not enough data to copy');
    }

    let resultBuffer = Buffer.allocUnsafe(bytesToCopy);
    let bytesRemaining = bytesToCopy;
    let offset = 0;

    for (let buffer of bufferList) {
        if (buffer.length < bytesRemaining) {
            buffer.copy(resultBuffer, offset);
            offset += buffer.length;
            bytesRemaining -= buffer.length;
        } else {
            let slice = buffer.slice(0, bytesToCopy);
            slice.copy(resultBuffer, offset);
            break;
        }
    }

    return resultBuffer;
}
```
