JavaScript inline function that copies a specified number of bytes from a list of buffered data chunks would look something like this:

```javascript
function copyBytes(buffers, byteCount) {
    var totalLength = buffers.reduce((acc, buffer) => acc + buffer.length, 0);

    if (byteCount > totalLength) {
        throw new Error('Requested more bytes than available');
    }

    var resultBuffer = Buffer.allocUnsafe(byteCount);
    var copiedBytes = 0;

    for (var i = 0; i < buffers.length && copiedBytes < byteCount; ++i) {
        var buffer = buffers[i];

        if (copiedBytes + buffer.length <= byteCount) {
            // If the whole buffer can be copied, copy it directly
            buffer.copy(resultBuffer, copiedBytes);
            copiedBytes += buffer.length;
        } else {
            // Otherwise, copy only part of it
            var bytesToCopy = byteCount - copiedBytes;
            buffer.slice(0, bytesToCopy).copy(resultBuffer, copiedBytes);
            copiedBytes += bytesToCopy;
        }
    }

    return resultBuffer;
}
```

