function readBytesFromBuffer(bufferList, numOfBytes) {
    let result = Buffer.allocUnsafe(numOfBytes); // allocate memory for the new buffer 
    let bytesRead = 0;

    for (let i = 0; i < bufferList.length && bytesRead < numOfBytes; i++) {
        const copyLength = Math.min(bufferList[i].length, numOfBytes - bytesRead);
        bufferList[i].copy(result, bytesRead, 0, copyLength);
        bytesRead += copyLength;
