['Here is a simplified version of how the code might look like. This is just a skeleton and you'll need to fill in the actual implementation for your specific use case, which includes error handling, logging framework integration, thread safety, circular reference checking and memory management optimization.

```cpp
#include <iostream>
#include <fstream>
#include <map>
#include <stack>
#include <mutex>
#include <tinyxml2.h>  //TinyXML is a simple, small, C++ XML parser that can be easily integrating into your application.

std::mutex mtx;           // mutex for critical section

class ConfigLoader {
    std::map<std::string, bool> visitedNodes;
    std::stack<std::string> nodeStack;
public: 
    void loadConfigFromXML(const char* filePath) {
        tinyxml2::XMLDocument doc;
        doc.LoadFile(filePath);

        if (doc.ErrorID()) {
            std::cout << "Failed to load XML file." << std::endl;
            return;
        }

        mtx.lock();    // Lock the mutex before accessing shared data

        tinyxml2::XMLElement* root = doc.FirstChildElement();
        processNode(root);

        mtx.unlock();  // Unlock the mutex after finish accessing shared data
    }

private:
    void processNode(tinyxml2::XMLElement* node) {
        if (!node) return;
        std::string name = node->Value();

        if (visitedNodes.find(name) != visitedNodes.end()) {
            // Detect circular reference
            std::cout << "Circular reference detected: ";

            while (!nodeStack.empty()) {
                std::cout << nodeStack.top() << "->";
                nodeStack.pop();
            }

            return;
        }

        visitedNodes[name] = true;  // Mark the node as visited
        nodeStack.push(name);       // Push it into stack for circular reference detection

        std::cout << "Processing node: " << name << std::endl;

        tinyxml2::XMLElement* child = node->FirstChildElement();
        while (child) {
            processNode(child);  // Recursively process all children nodes
            child = child->NextSiblingElement();
        }

        visitedNodes.erase(name);   // Remove the node from visited after processing
        nodeStack.pop();           // Pop it from stack
    }
};
```

For unit testing, you can use libraries such as Google Test (gtest). Here is an example of how to write a test for the code:

