#include <mutex>

class RealTimeDataPipelineFramework {
public:
    void insertStringAfter(std::forward_list<std::string>& flist, 
                            const std::string& searchStr, 
                            const std::string& insertStr) {
        // Lock the mutex before performing any operations to ensure thread safety.
        std::lock_guard<std::mutex> lock(mtx);

        auto it = find(flist.begin(), flist.end(), searchStr);
        if (it != flist.end()) { 
            // The iterator 'it' now points to the element after the first occurrence of 'searchStr'.
            ++it;
            flist.insert_after(it, insertStr);
        } else {
            flist.push_back(insertStr);
        }
    }

private:
    std::mutex mtx;  // Mutex for ensuring thread safety.
};
```
