    if (!json_is_integer(expires_in) || json_integer_value(expires_in) < 0 || json_integer_value(expires_in) > 3600) {
        handle_error("Invalid expires_in");
    }
    // Add more validations as needed... 
}

void *handle_requests(void *arg) {
    while (1) {
        CURL *curl = curl_easy_init();

        if (!curl) {
            handle_error("Failed to initialize curl");
        }

        // Setup curl options and perform request
        // ... 

        json_t *root;
        json_error_t error;
        root = json_loads(response, 0, &error);

        if (!root) {
            handle_error("Failed to parse JSON");
        }

        validate_json(root);

        // Update global state
        access_token = strdup(json_string_value(json_object_get(root, "access_token")));
        expires_in = json_integer_value(json_object_get(root, "expires_in"));
        token_type = strdup(json_string_value(json_object_get(root, "token_type")));

        // If refresh_token is present 
        if (json_object_get(root, "refresh_token") != NULL) {
            refresh_token = strdup(json_string_value(json_object_get(root, "refresh_token")));
        }

        json_decref(root);
    }
}

int main() {
    // Initialize curl 
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Create threads 
    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, handle_requests, NULL);
    }

    // Join threads 
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    curl_global_cleanup();

    return 0;
}
