void insertStringAtPosition(std::forward_list<std::string>& list, const std::string& str, size_t pos) {
    std::lock_guard<std::mutex> lock(mtx);  // Lock mutex to prevent concurrent modifications.

    auto it = list.before_begin();  // Initialize iterator at before the start of the list.
