["Here is a high level code example. Due to the complexity of this task, this example is just about the basics and is not fully functional or suitable for production environment. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct State {
    char* name;
    void (*on_enter)(void);
    void (*on_exit)(void);
} State;

typedef struct FSA {
    pthread_t thread;
    int running;
    int persistence_interval;

    int num_states;
    State** states;
    State* current_state;

    void (*on_data)(char*, int);
} FSA;

FSA* fsa_create() {
    FSA* fsa = malloc(sizeof(FSA));
    fsa->num_states = 0;
    fsa->current_state = NULL;
    return fsa;
}

void fsa_destroy(FSA* fsa) {
    fsa->running = 0;
    pthread_join(fsa->thread, NULL);

    for (int i = 0; i < fsa->num_states; ++i) {
        free(fsa->states[i]->name);
        free(fsa->states[i]);
    }
    free(fsa->states);

    free(fsa);
}

void fsa_add_state(FSA* fsa, char* name, void (*on_enter)(void), void (*on_exit)(void)) {
    State** new_arr = realloc(fsa->states, sizeof(State*) * (fsa->num_states + 1));

    if (new_arr) {
        fsa->states = new_arr;

        State* state = malloc(sizeof(State));
        state->name = strdup(name);
        state->on_enter = on_enter;
        state->on_exit = on_exit;

        fsa->states[fsa->num_states++] = state;
    }
}

void* thread_function(void* arg) {
    FSA* fsa = (FSA*)arg;

    while (fsa->running) {
        sleep(fsa->persistence_interval);

        // Persist state here
    }

    return NULL;
}

void fsa_start(FSA* fsa, int persistence_interval) {
    fsa->running = 1;
    fsa->persistence_interval = persistence_interval;
    pthread_create(&fsa->thread, NULL, thread_function, (void*)fsa);
}
```

This code is a simple example of a state machine with some basic concurrent functionality. The `on_data` callback can be used to handle asynchronous updates from an external data source. 

