["Implementing such a comprehensive library as per the specification in a single response would be quite complex and lengthy due to the complexity involved. However, below is a simplified outline of how you could approach implementing this library in C. Please note that this is just an example and doesn't cover all requirements like error handling, logging or connection pooling, but it gives a high-level idea of how such library might be implemented.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    INITIATED,
    CONNECTED,
    DISCONNECTED,
} ConnectionState;

typedef struct {
    char* SessionID;
    char* PeerAddress;
    ConnectionState state;
} Connection;

typedef struct Node {
    Connection *conn;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addConnection(char* SessionID, char* PeerAddress, ConnectionState state) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->conn = malloc(sizeof(Connection));
    newNode->conn->SessionID = strdup(SessionID);
    newNode->conn->PeerAddress = strdup(PeerAddress);
    newNode->conn->state = state;
    newNode->next = head;

    head = newNode;

    pthread_mutex_unlock(&lock);
}

void updateConnectionState(char* SessionID, ConnectionState state) {
    pthread_mutex_lock(&lock);

    Node *temp = head;
    while (temp != NULL) {
        if (strcmp(temp->conn->SessionID, SessionID) == 0) {
            temp->conn->state = state;
            break;
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}

void removeConnection(char* SessionID) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev = NULL;
    while (temp != NULL && strcmp(temp->conn->SessionID, SessionID) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Connection not found

    if (prev != NULL) prev->next = temp->next;

    if (head == temp) head = temp->next;

    free(temp->conn->SessionID);
    free(temp->conn->PeerAddress);
    free(temp->conn);
    free(temp);

    pthread_mutex_unlock(&lock);
}
``` 
This is a very basic implementation and doesn't take into account many factors such as memory management, error handling, thread safety, integration with an external data store or performance considerations for large number of connections. Real-world implementations would likely involve more intricate design decisions and additional libraries/frameworks like libevent, glibc, pthreads etc.
