app.use(bodyParser.json()); // Parse JSON bodies

// Define routes
app.post('/transactions', async (req, res) => {
    try {
        const transaction = req.body;

        // Validate transaction data
        if(!transaction || !transaction.amount || !transaction.currency) {
            return res.status(400).send({error: 'Invalid transaction data'});
        }

        // Process transaction with payment gateway 
        const result = await paymentGateway.processTransaction(transaction);

        if (result.status === "success") {
            return res.status(200).send({ message: 'Transaction successful' });
        } else {
            return res.status(500).send({ error: result.message });
        }
    } catch (error) {
        // Handle any unexpected errors
        console.error(error);
        return res.status(500).send({ error: 'An unexpected error occurred' });
    }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke');
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server is listening on port ${port}`));
```
