However, I will provide you with some basic code snippets that could serve as starting points for your project:

Here's a simple implementation of union-find data structure in Rust:
```rust
pub struct UnionFind {
    id: Vec<usize>,
}

impl UnionFind {
    pub fn new(size: usize) -> Self {
        Self { 
            id: (0..size).collect(), 
        }
    }

    pub fn root(&mut self, i: usize) -> usize {
        let mut i = i;
        while i != self.id[i] {
            self.id[i] = self.id[self.id[i]];  // path compression by halving
            i = self.id[i];
        }
        i
    }

    pub fn union(&mut self, p: usize, q: usize) {
        let i = self.root(p);
        let j = self.root(q);
        self.id[i] = self.id[j];
    }

    pub fn connected(&mut self, p: usize, q: usize) -> bool {
        self.root(p) == self.root(q)
    }
}
```
