[ApiController]
public class HtmlUpdateController : ControllerBase
{
    private static readonly SemaphoreSlim semaphore = new SemaphoreSlim(1, 1);
    private readonly IHtmlSanitizer _htmlSanitizer;
    private readonly ICmsService _cmsService;
    private readonly IPublishEndpoint _publishEndpoint;
    private static MemoryCache _cache;

    public HtmlUpdateController(IHtmlSanitizer htmlSanitizer, ICmsService cmsService, IPublishEndpoint publishEndpoint)
    {
        _htmlSanitizer = htmlSanitizer;
        _cmsService = cmsService;
        _publishEndpoint = publishEndpoint;
        _cache = new MemoryCache(new MemoryCacheOptions
        {
            SizeLimit = 1024 // you can customize cache limit according to your needs.
        });
    }

    [HttpPost("update-html")]
    public async Task<IActionResult> UpdateHtml([FromBody] HtmlUpdateDto dto)
    {
        if (!ModelState.IsValid || !IsBelongToSamePageSection(dto)) 
            return BadRequest();

        var sanitizedContent = _htmlSanitizer.Sanitize(dto.HtmlContent);

        // Check cache before updating the CMS service.
        if (_cache.TryGetValue(dto, out bool cachedResult) && (bool)cachedResult == true) 
            return Ok("No need for page refresh");

        try
        {
            await semaphore.WaitAsync();

            var result = await _cmsService.UpdateContent(sanitizedContent);

            if (result)
            {
                await _publishEndpoint.Publish<PageRefreshEvent>(new 
                {
                    PageId = dto.PageSectionId,
                    ElementId = dto.ElementId,
                    SanitizedHtmlContent = sanitizedContent
                });

                // Update cache and release semaphore after successful update.
                _cache.Set(dto, true);
            }

            return Ok("Page refresh needed");
        }
        catch (Exception ex)
        {
            // Handle exceptions here
        } 
        finally
        {
            semaphore.Release();
        }
    }

    private bool IsBelongToSamePageSection(HtmlUpdateDto dto)
    {
       // Implement logic to verify that the provided IDs belong to the same page section.
    } 
}
```
This code assumes usage of an IHtmlSanitizer interface, a simple DTO class named HtmlUpdateDto, an ICmsService interface for integrating with external CMS service and a PageRefreshEvent class representing the message published to distributed queue. All dependencies should be registered in your DI container. 

