    libraries: HashMap<String, Arc<Library>>,
    cache: CacheService,
    web_framework: WebFrameworkService,
}

impl ScriptManager {
    fn new() -> Self {
        // initialize services and dependencies here
        ScriptManager { libraries: HashMap::new(), cache: CacheService::new(), web_framework: WebFrameworkService::new() }
    }

    async fn load(&self, library: Library) -> Result<JoinHandle<()>, ()> {
        if let Some(lib) = self.cache.get(&library.name) {
            // check cache first for quick response
            return Ok(tokio::spawn(load_script(lib)));
        } else {
            match self.web_framework.fetch(&library).await {
                Err(_) => return Err(()),
                Ok(new_library) => {
                    let cache_handle = tokio::spawn(self.cache.set(Arc::clone(&new_library))); // spawn a task to cache the library 
                    cache_handle.map(|_| load_script(Arc::clone(&new_library))) // return a handle that loads the script when caching is done
                }
            }
        }
    }
}

#[tokio::main]
