        self.handlers.append(handler)

    def handle(self, log):
        for h in self.handlers:
            try:
                # Implement a circuit breaker pattern.
                if not h.is_available():
                    logging.warning('Service is unavailable.')
                    continue

                while True:
                    try: 
                        h.send_log(log)
                        self._exponential_backoff = 1
                        break  

                    except Exception as e: # Assuming all exceptions are transient errors.
                        logging.warning('Error occurred when sending log, retrying...')
                        time.sleep(self._exponential_backoff) 

                        if self._exponential_backoff < 10:
                            self._exponential_backoff *= 2

        logging.warning('All handlers are unavailable, dropping the log.')                

    def info(self, msg):
        # Implement customizable log levels and formats here... 
        pass

class Application:
    def __init__(self):
        self.logger = CustomLogger()

        elk_stack_handler = ElkStack()
        self.logger.addHandler(elk_stack_handler)
```
