const express = require('express');
const bodyParser = require('body-parser');
const transactionService = require('./services/transactionService');
const fraudDetectionService = require('./services/fraudDetectionService');
const regulatoryComplianceService = require('./services/regulatoryComplianceService');

const app = express();
app.use(bodyParser.json());

app.post('/transactions', async (req, res) => {
    // Validate the transaction request
    const validationResult = await transactionService.validateTransaction(req.body);
    if (!validationResult.valid) {
        return res.status(400).json({ error: validationResult.error });
    }

    // Perform fraud detection checks
    const fraudDetectionResult = await fraudDetectionService.detectFraud(req.body);
    if (fraudDetectionResult.isFraud) {
        return res.status(403).json({ error: 'Fraud detected' });
    }

    // Check for regulatory compliance
    const complianceCheckResult = await regulatoryComplianceService.checkCompliance(req.body);
    if (!complianceCheckResult.compliant) {
        return res.status(403).json({ error: 'Non-compliant transaction' });
    }

    // If all checks pass, process the transaction
    const result = await transactionService.processTransaction(req.body);
    res.json(result);
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server listening on port ${port}`));
```

