using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace WebsiteMD5Service
{
    public class MD5Service : IMD5Service
    {
        private readonly IConfigurationRepository _configurationRepository;
        private readonly ILoggingService _loggingService;

        public MD5Service(IConfigurationRepository configurationRepository, ILoggingService loggingService)
        {
            _configurationRepository = configurationRepository;
            _loggingService = loggingService;
        }

        public async Task<string> ComputeMD5Async(string inputString)
        {
            try
            {
                // Check if the web.config file exists in the specified directory
                var configExists = await _configurationRepository.CheckWebConfigExistence();

                if (!configExists) 
                    throw new Exception("web.config not found. Please make sure it's included.");

                byte[] inputBytes = Encoding.ASCII.GetBytes(inputString);
                byte[] hashBytes;

                using (var md5 = MD5.Create())
                {
                    hashBytes = md5.ComputeHash(inputBytes);
                }

                StringBuilder sb = new StringBuilder();

                for (int i = 0; i < hashBytes.Length; i++) 
                {
                    sb.Append(hashBytes[i].ToString("X2"));
                }

                // Store the computed MD5 hash in a database or any other storage
                await _configurationRepository.StoreMD5HashAsync(sb.ToString());

                return sb.ToString();
            }
            catch (Exception ex)
            {
                _loggingService.LogError("An error occurred while computing the MD5 hash", ex);

                throw;
            }
        }
    }
}
```

