        }
    }, 
});
```
2. **Async File Upload:** You can use libraries like Async, Bluebird or native promises to handle asynchronous operations. Here's an example using async/await and axios for sending requests:

```javascript
const axios = require('axios');

app.post('/upload', upload.single('file'), async (req, res) => {
    try {
        const response = await axios({
            method: 'POST',
            url: '/api/files',
            data: req.file.buffer,
        });

        if (response.status === 200) {
            res.send('File uploaded successfully');
