    memcpy(user->key, key, 32);

    return user;
}

// Encrypt some data with the given user's key
unsigned char* encrypt_data(User* user, const unsigned char* plaintext, int len, int* outlen) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Generate a fresh IV for each encryption operation
    unsigned char iv[16]; // AES block size is 128 bits = 16 bytes
    RAND_bytes(iv, 16);

    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, user->key, iv);

    int ciphertextlen = len + (EVP_CIPHER_CTX_block_size(ctx) - len % EVP_CIPHER_CTX_block_size(ctx));
    unsigned char* ciphertext = malloc(ciphertextlen);

    int updatelen = 0;
    EVP_EncryptUpdate(ctx, ciphertext, &updatelen, plaintext, len);
    *outlen = updatelen;

    // Store the IV securely (e.g., in a database along with the ciphertext)
    // You might want to use an encryption function here as well, depending on your security needs

    EVP_EncryptFinal_ex(ctx, ciphertext + updatelen, &updatelen);
    *outlen += updatelen;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext;
}
