```C
#include <stdio.h>
#include <stdlib.h>

typedef struct MedianFinder {
    int *arr;
    int size;
} MedianFinder;

MedianFinder* mfCreate() {
    MedianFinder *obj = (MedianFinder*)malloc(sizeof(MedianFinder));
    obj->arr = NULL;
    obj->size = 0;
    return obj;
}

void mfAddNum(MedianFinder* obj, int num) {
    // Dynamic resizing of array
    obj->arr = (int*)realloc(obj->arr, (++obj->size)*sizeof(int));
    obj->arr[obj->size - 1] = num;
}

double mfFindMedian(MedianFinder* obj) {
    // Simple bubble sort for finding median
    int *sortedArr = (int*)malloc(obj->size * sizeof(int));
    memcpy(sortedArr, obj->arr, obj->size * sizeof(int));

    for(int i = 0; i < obj->size - 1; ++i) {
        for(int j = i + 1; j < obj->size; ++j) {
            if(sortedArr[i] > sortedArr[j]) {
                int temp = sortedArr[i];
                sortedArr[i] = sortedArr[j];
                sortedArr[j] = temp;
            }
        }
    }

    double median = 0.0;
    if(obj->size % 2 == 1) {
        // Odd number of elements
        median = (double)sortedArr[(obj->size - 1) / 2];
    } else {
        // Even number of elements
        int midIndex1 = (obj->size - 1) / 2;
        int midIndex2 = obj->size / 2;
        median = ((double)(sortedArr[midIndex1] + sortedArr[midIndex2])) / 2.0;
    }

    free(sortedArr);
    return median;
}
```
This is a simplified version of the code which only handles adding numbers and finding the median in a data stream. It's not real-time, doesn't integrate with external API, or handle multi-threading. 

