1. File Processing - You can use `fs` module in Node.js to read files from directories and handle multiple file extensions. The async/await pattern can be used for handling asynchronous processing. Here's a simple example:
```javascript
const fs = require('fs');
const path = require('path');

async function processFiles(dir, depth) {
  if (depth === 0) return;

  const files = await fs.promises.readdir(dir);

  for (let file of files) {
    const fullPath = path.join(dir, file);
    const stat = await fs.promises.stat(fullPath);

    if (stat.isDirectory()) {
      processFiles(fullPath, depth - 1);
    } else {
      // Process the file here
    }
  }
}
```
This function recursively processes all files in a directory and its subdirectories up to a certain depth. You can add filters for file size and extensions as needed.

