['Here is a high-level pseudocode for the problem you described, considering many details that would go into an actual implementation. 

```cpp
#include <iostream>
#include <cstdio>
#include <curl/curl.h>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>
#include <atomic>

// Define a retry policy structure that can be customized by admins
struct RetryPolicy {
  int maxRetries; // Max number of retries
  std::chrono::seconds timeWindow; // Time window for rate limiting
};

std::mutex curl_easy_init_mutex;
std::atomic<int> currentConcurrentRequests(0);
const int MAX_CONCURRENT_REQUESTS = 1000; 
TokenBucket throttleTokenBucket; // Assuming this is a hypothetical token bucket class
DistributedLatencyMonitor latencyMonitor; // Assuming this is a hypothetical distributed latency monitor
Logger logger; // Assuming this is a hypothetical logger class

size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
  ((std::string*)userp)->append((char*)contents, size * nmemb);
  return size * nmemb;
}

int makeRequestWithRetry(const std::string& url, const RetryPolicy& retryPolicy, int retryCount = 0) {
    // Check if we've hit the max concurrent request limit
    if (currentConcurrentRequests >= MAX_CONCURRENT_REQUESTS) {
        logger.log("Max concurrent requests reached");
        return -1;  // Return error code to indicate failure
    }
    ++currentConcurrentRequests;
    std::lock_guard<std::mutex> lock(curl_easy_init_mutex); // Ensure thread safety while initializing curl
    CURL* handle = curl_easy_init(); 
    --currentConcurrentRequests;

    if (throttleTokenBucket.getTokens() <= 0) {
        logger.log("Rate limited");
        std::this_thread::sleep_for(std::chrono::seconds(retryPolicy.timeWindow)); // Sleep to wait for tokens
    } else {
      throttleTokenBucket.consume();
    }

    if (!handle) {
        logger.log("Failed to initialize curl");
        return -1;  // Return error code to indicate failure
    }

    std::string readBuffer;
    CURLcode res;
    curl_easy_setopt(handle, CURLOPT_URL, url.c_str());
    curl_easy_setopt(handle, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(handle, CURLOPT_WRITEDATA, &readBuffer);

    res = curl_easy_perform(handle); // Perform the request
    long httpCode = 0;
    curl_easy_getinfo(handle, CURLINFO_RESPONSE_CODE, &httpCode);

    if (res != CURLE_OK || httpCode >= 400) { 
        logger.log("Request failed with error: " + std::string(curl_easy_strerror(res)));
        // Check if we should retry
        if (retryCount < retryPolicy.maxRetries) {
            logger.log("Retrying...");
            std::default_random_engine generator;
            std::uniform_int_distribution<int> distribution(0, (1 << retryCount));
            int sleepTime = distribution(generator);
            std::this_thread::sleep_for(std::chrono::seconds(sleepTime)); // Sleep for a jitter time

            return makeRequestWithRetry(url, retryPolicy, retryCount + 1);
        } else {
            logger.log("Max retries reached");
        }
    } else {
      latencyMonitor.reportLatency(std::chrono::duration_cast<std::chrono::milliseconds>( // Report network request latency
              std::chrono::system_clock::now().time_since_epoch()).count() - httpCode);
    }

    curl_easy_cleanup(handle);

    return 0; // Return success code if everything went well
}
```

This is a simplified pseudo-code that includes the key features you asked for. It uses libcurl to make network requests, std::thread and std::chrono for timing operations, C++11 random number generation for jitter, std::atomic for concurrency control and safety, and std::mutex for thread safety during curl initialization.

Please note that it's very difficult to provide the full implementation in just a few lines of code due to the complexities involved in this task. This pseudo-code is intended as a starting point and may require further refining or adjustments based on your specific requirements and constraints. 

Also, be aware that libcurl does not handle HTTP error codes consistently across platforms and it may be necessary to use platform-specific libraries for better handling of HTTP responses. Please replace with an actual implementation suitable for your platform if needed.
