For C# service:
```csharp
using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Azure.Documents.Client; //For NoSQL Database interaction
using StackExchange.Redis; //For Caching

public class WebsiteService {
    private readonly ILogger<WebsiteService> _logger;
    private static MD5 _md5 = MD5.Create();
    private DocumentClient _dbClient;
    private ConnectionMultiplexer _redis;

    public WebsiteService(ILogger<WebsiteService> logger, DocumentClient dbClient, ConnectionMultiplexer redis) {
        _logger = logger;
        _dbClient = dbClient;
        _redis = redis;
    }

    public async Task<string> ComputeMD5Async(string input) {
        // Use Redis for caching and fallback to compute MD5 when not available in cache
        IDatabase database = _redis.GetDatabase();
        string cachedHash = await database.StringGetAsync(input);

        if (cachedHash != null)  {
            return cachedHash;
        } else {
            byte[] inputBytes = System.Text.Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = _md5.ComputeHash(inputBytes);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++) {
                sb.Append(hashBytes[i].ToString("X2"));
            }

