```csharp
public class Service : IService
{
    private readonly IKeyProvider _keyProvider;
    private readonly ISecretStore _secretStore;
    private readonly IDistributedCache _distributedCache;
    private readonly ILogger<Service> _logger;
    private static ReaderWriterLockSlim cacheLock = new ReaderWriterLockSlim();

    public Service(IKeyProvider keyProvider, ISecretStore secretStore, 
                    IDistributedCache distributedCache, ILogger<Service> logger)
    {
        _keyProvider = keyProvider;
        _secretStore = secretStore;
        _distributedCache = distributedCache;
        _logger = logger;
    }

    public async Task<Dictionary<string, string>> ProcessMessages(List<Message> messages)
    {
        var result = new Dictionary<string, string>();

        foreach (var message in messages)
        {
            try
            {
                var keyId = message.KeyIdentifier;
                var secret = await _secretStore.GetSecretAsync(keyId);

                if (_distributedCache.TryGetValue(message.ContentHash, out string decryptedMessage)) 
                    result.Add(message.Id, decryptedMessage);
                else
                {
                    var aesKey = await _keyProvider.GetDecryptionKeyAsync(secret.SecretValue);

                    var decryptedMessage = AESHelper.Decrypt(message.Content, aesKey, secret.Iv);

                    if (HMACSHA256Helper.Verify(decryptedMessage, message.Signature))
                    {
                        cacheLock.EnterWriteLock();
                        try
                        {
                            _distributedCache.Set(message.ContentHash, decryptedMessage);
                        }
                        finally
                        {
                            cacheLock.ExitWriteLock();
                        }

                        result.Add(message.Id, decryptedMessage);
                    } 
                    else
                    {
                        _logger.LogError("Signature verification failed for message with id: " + message.Id);
                        throw new InvalidDataException("Invalid signature");
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process message with id: " + message.Id);
                throw; // or some more appropriate exception handling
            }
        }

        return result;
    }
}
```
