    public class AesDecryptionService : IDecryptionService
    {
        private readonly byte[] _key;
        private readonly byte[] _iv;
        private readonly PaddingMode _paddingMode;

        public AesDecryptionService(byte[] key, byte[] iv, PaddingMode paddingMode)
        {
            _key = key;
            _iv = iv;
            _paddingMode = paddingMode;
        }

        public string DecryptCipherText(string ciphertext)
        {
            using var aesAlgorithm = Aes.Create();
            aesAlgorithm.Key = _key;
            aesAlgorithm.IV = _iv;
            aesAlgorithm.Padding = _paddingMode;

            var decryptor = aesAlgorithm.CreateDecryptor(aesAlgorithm.Key, aesAlgorithm.IV);

            byte[] cipherBytes = Convert.FromBase64String(ciphertext);
            byte[] plainBytes = decryptor.TransformFinalBlock(cipherBytes, 0, cipherBytes.Length);

            return Encoding.UTF8.GetString(plainBytes);
        }
    }

    public interface IDecryptionService
    {
        string DecryptCipherText(string ciphertext);
    }
}
```

