```cpp
#include <queue>
#include <condition_variable>

template<typename T>
class ConcurrentQueue {
public:
    void push(T const& data) {
        std::unique_lock<std::mutex> lock(_mtx);
        _data.push(data);
        lock.unlock();
        _condVar.notify_one();
    }

    T waitAndPop() {
        std::unique_lock<std::mutex> lock(_mtx);

        while (_data.empty()) {
            _condVar.wait(lock);
        }

        auto wst = _data.front();
        _data.pop();
        return wst;
    }

private:
    std::queue<T> _data;
    std::mutex _mtx;
    std::condition_variable _condVar;
};
```
Please note, this is a basic example and doesn't include all possible optimizations or error handling. You would need to implement these parts based on your specific requirements. 

