#include <stdio.h>
#include <stdlib.h>

typedef struct {
    // assuming each item in the bundle is a string for simplicity 
    char* items;
} ResourceBundle;

int load_resource_bundle(const char* path, ResourceBundle** bundle) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        // error opening the file
        return -1;
    }

    int count = 0;  // for simplicity, assume each line is an item in the bundle
    char buf[256];
    while(fgets(buf, sizeof(buf), file)) {
        ++count;
    }

    *bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    (*bundle)->items = (char**)malloc(sizeof(char*) * count);
    if ((*bundle)->items == NULL) {
        // error allocating memory
        free(*bundle);
        fclose(file);
        return -2;
    }

    rewind(file);  // reset file pointer to the beginning of the file
    int i = 0;
    while(fgets((*bundle)->items[i], sizeof(buf), file)) {
        ++i;
    }

    fclose(file);
    return count;
}
```
