};

class StreamAndTransformData{
public:
  // Constructor and destructor
  StreamAndTransformData(std::vector<std::string> frequencies, ProcessingMode mode) : processing_mode_(mode), frequencies_(frequencies) {
    for (const auto& freq : frequencies_) {
      data_.emplace(freq, std::queue<DataItem>());
    }
  };

  ~StreamAndTransformData(){};

  // Method to process incoming data
  void ProcessIncomingData(std::string frequency, int value){
    if (processing_mode_ == REALTIME) {
      std::lock_guard<std::mutex> lock(data_[frequency].m_);
      DataItem item = {frequency, value};
      data_[frequency].q_.push(item);
      cv_.notify_one();
    } else if (processing_mode_ == BATCH) {
      // Processing for batch mode...
    }
  };

private:
  struct DataQueue {
    std::queue<DataItem> q_;
    std::mutex m_;
    std::condition_variable cv_;
  };

  std::map<std::string, DataQueue> data_; // Stores queues for each frequency
  ProcessingMode processing_mode_;
  std::vector<std::string> frequencies_;
};
```
This is a basic example and does not include many of the complexities you described such as network latency, concurrent processing, data sampling, error handling, etc. Also, note that this design assumes a single writer multiple reader scenario for the queues which might not be suitable in high-load scenarios where locks can become a bottleneck. For these scenarios, consider using a lock-free data structure or use a ring buffer if you have a fixed upper bound on size of your queue.
