class TLSConnection {
public:
    explicit TLSConnection(io::io_context& ioc, ssl::context& ctx) : socket_(ioc, ctx) {}

    void start() {
        // Perform handshake.
        auto self = shared_from_this();
        socket_.async_handshake(ssl::stream_base::client, [self](error_code ec){ 
