['This problem is a bit too large for me to provide full solution but here's a brief outline of how you might tackle this using Flask as the main backend API framework, SQLAlchemy for database operations, Celery/RQ for background tasks, Redis for queuing and cache. 

1. Create your flask application, and define the models in it.
```python
from flask import Flask
from flask_sqlalchemy import SQLAlchemy
import hashlib, binascii

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'your_database_uri'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50))
    email = db.Column(db.String(120), unique=True)
    password_hash = db.Column(db.String(128))  # For hashed passwords.

    def hash_password(self, password):
        """Convert the provided password to a hash for secure storage."""
        pwd_hash = hashlib.pbkdf2_hmac('sha512', password.encode(), salt, 100000)
        pwd_hash = binascii.hexlify(pwd_hash)
        return pwd_hash.decode('ascii')
```
2. Implement the user endpoints:
```python
from flask import request, jsonify
@app.route('/user', methods=['POST'])
def create_or_update_user():
    data = request.get_json()
    action = data.pop('sub_action')

    if not all(k in data for k in ("name", "email", "password")):
        return jsonify({'message': 'Missing fields!'}), 400

    user = User.query.filter_by(email=data['email']).first()

    if action == 'create':
        if user:
            return jsonify({'message': 'User already exists!'})

        new_user = User(**data)
        db.session.add(new_user)

    elif action == 'update':
        if not user:
            return jsonify({'message': 'User does not exist!'}), 400

        for k, v in data.items():
            setattr(user, k, v)

    else:
        return jsonify({'message': 'Invalid action!'})

    db.session.commit()
    return jsonify({'message': f'User {action} successful.'}), 200
```
3. Implement the delete endpoint with idempotent deletion:
```python
@app.route('/user', methods=['DELETE'])
def delete_user():
    data = request.get_json()

    user = User.query.filter_by(email=data['email']).first()
    if not user:
        return jsonify({'message': 'User does not exist!'}), 400

    db.session.delete(user)
    db.session.commit()

    return jsonify({'message': 'Delete successful.'})
```
For the fetching integers part, you can use celery tasks and requests library to fetch from external APIs:
```python
from celery import Celery
import requests
app = Celery('tasks', backend='your_backend', broker='your_broker')
@app.task(bind=True)
def fetch_integers(self, url):
    response = requests.get(url)

    if response.status_code != 200:
        raise self.retry(countdown=60)  # Retry after a minute if request fails.

    return response.json()
```
For the median calculation part, you can use NumPy or Pandas libraries in Python as they are designed for efficient calculations on large datasets:
```python
import numpy as np
def calculate_median(data):
    return np.median(data)
```
To ensure high availability and handle heavy loads, use a load balancer like Nginx to distribute the requests across multiple instances of your application and Redis for caching and message queueing. For comprehensive logging and monitoring, use Flask's built-in logger or third party tools such as Sentry or Logstash.
']

