['This task is extremely complex and cannot be fully realized within the scope of this platform due to its complexity. However, I can sketch a very basic example of how you might structure such a system in Rust. This would require extensive development time, testing, and refinement before it could serve as a production-ready distributed storage library:

```rust
use std::collections::HashMap;
use std::time::{Duration, Instant};
use std::thread;
use std::sync::Arc;

pub struct DistributedFileSystem {
    nodes: Vec<Node>,
}

struct Node {
    data: Arc<HashMap<String, Vec<u8>>>,
}

impl DistributedFileSystem {
    pub fn new(node_count: usize) -> Self {
        let mut nodes = vec![];

        for _ in 0..node_count {
            nodes.push(Node { data: Arc::new(HashMap::new()) });
        }

        Self { nodes }
    }

    pub fn write(&self, key: String, value: Vec<u8>) -> Result<(), &str> {
        let start = Instant::now();

        for node in self.nodes.iter() {
            // simulate network latency and possible node failures
            thread::sleep(Duration::from_millis(100));

            if rand::random() {
                return Err("write failed");
            } else {
                node.data.insert(key.clone(), value);
            }
        }

        println_measuring_latency("write", start);

        Ok(())
    }

    pub fn read(&self, key: String) -> Option<Vec<u8>> {
        let mut result = None;

        for node in self.nodes.iter() {
            // simulate network latency and possible node failures
            thread::sleep(Duration::from_millis(100));

            if rand::random() {
                continue;
            } else {
                result = Some(node.data[&key].clone());
                break;
            }
        }

        println_measuring_latency("read", Instant::now());

        result
    }
}

