}

fn println_color<S1: AsRef<str>, S2: AsRef<str>>(color: S1, s: S2) {
    println_string(format_with_unit(color.as_ref(), s.as_ref()));
}

fn println_string<T: std::fmt::Display>(s: T) {
    println_string_literal("{}", s.as_ref());
}

fn println_string_literal<S1: AsRef<str>, S2: AsRef<str>>(s: S1, s2: S2) {
    println______(format_with_unit(s.as_ref(), s2.as_ref()));
}

fn format_with_unit<S1: AsRef<str>, S2: AsRef<str>>(s: S1, s2: S2) -> String {
    format_______(s.as_ref(), s2.as_ref())
}

pub fn println______(args: ::std::fmt::Arguments) {
    use std::io::Write;

    let stdout = ::std::io::stdout();
    let mut lock = stdout.lock();
    writeln____(lock, args).expect________("write failed");
}

fn writeln____<W: ::std::io::Write>(mut w: W, args: ::std::fmt::Arguments) -> Result<(), ::std::io::Error> {
    use std::io;

    w.write_fmt(args)?;
    io::Write::flush(&mut w)?;
    write_____(::std::io::stdout(), b"\n")?;
    Ok(())
}
```
