        {
            var timeCost = _configurations["timeCost"]; 
            var memoryCost = _configurations["memoryCost"];
            var parallelism = _configurations["parallelism"];
            var hashLength = _configurations["hashLength"];

            // Generate a secure salt of the appropriate length
            var salt = Utils.GetSecureSalt(); 

