However, keep in mind that such a large-scale project would typically involve more than just writing the code itself - it will also require careful planning, testing, and integration with other components of your system.

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Data fields for this structure.
} NFAPI_CRC_INDICATION_PDU_T;

// List Node Structure.
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *prev;
    struct Node *next;
} Node;

// List Head Structure.
typedef struct DoublyLinkedList {
    atomic_int size;
    pthread_mutex_t mutex;
    Node *head;
    Node *tail;
} DoublyLinkedList;

DoublyLinkedList list;

// Function to initialize the list.
void InitializeList() {
    list.size = 0;
    pthread_mutex_init(&list.mutex, NULL);
    list.head = NULL;
    list.tail = NULL;
}

// Function to add an element to the list (race condition handling included).
void AddElement(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list.mutex);  // Lock for thread safety.

    Node *newNode = malloc(sizeof(Node));   // Allocate memory for new node.
    if (newNode == NULL) {
        printf("Memory allocation failed.");
        exit(-1);
    }
    newNode->data = data;  // Set the data for new node.
    newNode->next = NULL;

    // If list is empty, set head and tail as this newly created node.
    if (list.head == NULL) {
        newNode->prev = NULL;
        list.head = newNode;
        list.tail = newNode;
    } else {  // Otherwise append to the end of the list.
        Node *lastNode = list.tail;
        lastNode->next = newNode;
        newNode->prev = lastNode;
        list.tail = newNode;
    }

    atomic_fetch_add(&list.size, 1); // Atomically increment size.
    pthread_mutex_unlock(&list.mutex);   // Unlock after operation is done.
}
```

This example only covers initializing the list and adding elements to it in a thread-safe way. A real-world implementation would involve much more, including memory allocation optimization, data validation against external databases, custom logging mechanism, comprehensive error handling, and extensive testing. 

