```php
<?php
require_once __DIR__ . '/vendor/autoload.php';

use Dotenv\Dotenv;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

class ApplicationInitializer {
    private $environment;
    private $logger;
    private $configFilePath;

    public function __construct($environment, $configFilePath) {
        $this->environment = $environment;
        $this->configFilePath = $configFilePath;
        $this->initLogger();
        $this->loadConfig();
    }

    private function initLogger() {
        // create a log channel
        $this->logger = new Logger('Application');
        $this->logger->pushHandler(new StreamHandler(__DIR__.'/logs/'.$this->environment.'.log', Logger::DEBUG));
    }

    private function loadConfig() {
        try {
            if (!file_exists($this->configFilePath)) {
                throw new Exception("Configuration file not found: " . $this->configFilePath);
            }

            $json = json_decode(file_get_contents($this->configFilePath), true);

            if (is_null($json)) {
                throw new Exception('Invalid configuration file format. JSON expected.');
            }

            $dotenv = Dotenv::createImmutable(__DIR__, '.env.' . $this->environment);
            $dotenv->load();
        } catch (Exception $e) {
            $this->logger->error('Failed to load configuration', ['exception' => $e]);
            exit(1);
        }
    }
}
```
You can expand on this basic structure to meet your requirements, for example adding more robust error handling and logging, implementing API calls for health checks or updates, etc.
