#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <stdatomic.h>  // for atomic operations

// Enum to represent the processing mode
enum ProcessingMode { PROCESSING_MODE_REAL_TIME, PROCESSING_MODE_BATCH };

class MarketDataProcessor {
public:
    MarketDataProcessor(ProcessingMode mode) : mode(mode), stopFlag(false) {}
    ~MarketDataProcessor() {
        stop();  // ensure that the thread stops if the object is destroyed
    }

    void start() {
        // Start the processing thread
        workerThread = std::thread(&MarketDataProcessor::worker, this);
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(m);
            stopFlag = true;
        }

        // Wake up the worker thread if it's waiting on the queue to be non-empty
        cond.notify_all();

        if (workerThread.joinable()) {
            workerThread.join();  // wait for the thread to finish
        }
    }

    void addMarketData(const std::string& data) {
        {
            std::lock_guard<std::mutex> lock(m);
            marketDataQueue.push(data);  // push the data into the queue
        }

        // Wake up the worker thread if it's waiting on the queue to be non-empty
        cond.notify_one();
    }

private:
    void worker() {
        std::unique_lock<std::mutex> lock(m);

        while (!stopFlag) {  // keep processing until stop is called
            if (marketDataQueue.empty()) {
                cond.wait(lock, [this]{ return !marketDataQueue.empty() || stopFlag; });
            } else {
                std::string data = marketDataQueue.front();
                marketDataQueue.pop();  // pop the processed data from the queue

                lock.unlock();

                process(data);  // process the data (replace with actual processing logic)

                lock.lock();
            }
        }
    }

    void process(const std::string& data) {
        if (mode == PROCESSING_MODE_REAL_TIME) {
            // Process real-time data here, using atomic operations for performance optimization
        } else if (mode == PROCESSING_MODE_BATCH) {
            // Accumulate and process batch data here
        }
    }

private:
    std::thread workerThread;  // the thread that processes market data
    ProcessingMode mode;  // processing mode (real-time or batch)
    bool stopFlag;  // flag to indicate that the thread should stop

    std::mutex m;  // mutex for synchronization
    std::condition_variable cond;  // condition variable for signaling between threads
    std::queue<std::string> marketDataQueue;  // queue of market data to be processed
};
